import "C"

import (
	"errors"
	"strings"
	"sync"
	"unsafe"
)

type DB struct {
	db *C.sqlite3
}

func openDB(path string) (*DB, error) {
	cpath := C.CString(path)
	defer C.free(unsafe.Pointer(cpath))
	var db *C.sqlite3
	rc := C.sqlite3_open_v2(cpath, &db, C.SQLITE_OPEN_READWRITE|C.SQLITE_OPEN_CREATE|C.SQLITE_OPEN_FULLMUTEX|C.SQLITE_OPEN_URI, nil)
	if rc != C.SQLITE_OK {
		msg := "unable to open database file"
		if db != nil {
			msg = C.GoString(C.sqlite3_errmsg(db))
			C.sqlite3_close_v2(db)
		}
		return nil, errors.New(msg)
	}
	d := &DB{db: db}
	registerFunctions(d)
	return d, nil
}

func (d *DB) Close() {
	if d.db != nil {
		C.sqlite3_close_v2(d.db)
		d.db = nil
	}
}

func (d *DB) errmsg() error {
	return errors.New(C.GoString(C.sqlite3_errmsg(d.db)))
}

type Stmt struct {
	d    *DB
	s    *C.sqlite3_stmt
	tail string
}

func (d *DB) Prepare(sql string) (*Stmt, error) {
	csql := C.CString(sql)
	defer C.free(unsafe.Pointer(csql))
	var st *C.sqlite3_stmt
	var tail *C.char
	rc := C.dsq_prepare(d.db, csql, &st, &tail)
	if rc != C.SQLITE_OK {
		return nil, d.errmsg()
	}
	t := ""
	if tail != nil && *tail != 0 {
		t = strings.TrimSpace(C.GoString(tail))
	}
	return &Stmt{d: d, s: st, tail: t}, nil
}

func (s *Stmt) Finalize() {
	if s.s != nil {
		C.sqlite3_finalize(s.s)
		s.s = nil
	}
}

func (s *Stmt) Reset() {
	C.sqlite3_reset(s.s)
	C.sqlite3_clear_bindings(s.s)
}

// Step returns true if a row is available.
func (s *Stmt) Step() (bool, error) {
	if s.s == nil {
		return false, nil
	}
	rc := C.sqlite3_step(s.s)
	switch rc {
	case C.SQLITE_ROW:
		return true, nil
	case C.SQLITE_DONE:
		return false, nil
	}
	// get detailed error
	C.sqlite3_reset(s.s)
	return false, s.d.errmsg()
}

func (s *Stmt) ColumnCount() int {
	if s.s == nil {
		return 0
	}
	return int(C.sqlite3_column_count(s.s))
}

func (s *Stmt) ColumnName(i int) string {
	return C.GoString(C.sqlite3_column_name(s.s, C.int(i)))
}

func (s *Stmt) ColumnDecltype(i int) string {
	p := C.sqlite3_column_decltype(s.s, C.int(i))
	if p == nil {
		return ""
	}
	return strings.ToLower(C.GoString(p))
}

// Column returns Go value: int64, float64, string, []byte, nil
func (s *Stmt) Column(i int) interface{} {
	ci := C.int(i)
	switch C.sqlite3_column_type(s.s, ci) {
	case C.SQLITE_INTEGER:
		return int64(C.sqlite3_column_int64(s.s, ci))
	case C.SQLITE_FLOAT:
		return float64(C.sqlite3_column_double(s.s, ci))
	case C.SQLITE_TEXT:
		p := C.sqlite3_column_text(s.s, ci)
		n := C.sqlite3_column_bytes(s.s, ci)
		return C.GoStringN((*C.char)(unsafe.Pointer(p)), n)
	case C.SQLITE_BLOB:
		p := C.sqlite3_column_blob(s.s, ci)
		n := C.sqlite3_column_bytes(s.s, ci)
		if p == nil || n == 0 {
			return []byte{}
		}
		return C.GoBytes(p, n)
	}
	return nil
}

func (s *Stmt) Bind(i int, v interface{}) error {
	ci := C.int(i)
	var rc C.int
	switch t := v.(type) {
	case nil:
		rc = C.sqlite3_bind_null(s.s, ci)
	case string:
		cs := C.CString(t)
		rc = C.dsq_bind_text(s.s, ci, cs, C.int(len(t)))
		C.free(unsafe.Pointer(cs))
	case []byte:
		if len(t) == 0 {
			rc = C.dsq_bind_blob(s.s, ci, nil, 0)
		} else {
			rc = C.dsq_bind_blob(s.s, ci, unsafe.Pointer(&t[0]), C.int(len(t)))
		}
	case bool:
		x := 0
		if t {
			x = 1
		}
		rc = C.sqlite3_bind_int64(s.s, ci, C.sqlite3_int64(x))
	case int:
		rc = C.sqlite3_bind_int64(s.s, ci, C.sqlite3_int64(t))
	case int64:
		rc = C.sqlite3_bind_int64(s.s, ci, C.sqlite3_int64(t))
	case float64:
		rc = C.sqlite3_bind_double(s.s, ci, C.double(t))
	default:
		return errors.New("unsupported bind type")
	}
	if rc != C.SQLITE_OK {
		return s.d.errmsg()
	}
	return nil
}

func (d *DB) Exec(sql string) error {
	for {
		st, err := d.Prepare(sql)
		if err != nil {
			return err
		}
		if st.s != nil {
			for {
				ok, err := st.Step()
				if err != nil {
					st.Finalize()
					return err
				}
				if !ok {
					break
				}
			}
		}
		st.Finalize()
		if st.tail == "" {
			return nil
		}
		sql = st.tail
	}
}

