	case string:
		return scalarShape("string")
	case float64, float32, int, int64, int32, int16, int8, uint, uint64, uint32, uint16, uint8, json.Number:
		return scalarShape("number")
	case bool:
		return scalarShape("boolean")
	}
	return unknownShape
}

func arrayShape(a []interface{}) *Shape {
	if len(a) == 0 {
		return &Shape{Kind: KindArray, Array: unknownShape}
	}
	var child *Shape
	n := len(a)
	if n > sampleSize {
		n = sampleSize
	}
	for i := 0; i < n; i++ {
		s := GetShape(a[i])
		if i == 0 {
			child = s
		} else {
			child = mergeShapes(child, s)
		}
	}
	return &Shape{Kind: KindArray, Array: child}
}

func shapeEqual(a, b *Shape) bool {
	if a.Kind != b.Kind {
		return false
	}
	switch a.Kind {
	case KindScalar:
		return a.Scalar == b.Scalar
	case KindUnknown:
		return true
	case KindArray:
		return shapeEqual(a.Array, b.Array)
	case KindObject:
		if len(a.Object) != len(b.Object) {
			return false
		}
		for k, av := range a.Object {
			bv, ok := b.Object[k]
			if !ok || !shapeEqual(av, bv) {
				return false
			}
		}
		return true
	case KindVaried:
		if len(a.Varied) != len(b.Varied) {
			return false
		}
		for i := range a.Varied {
			if !shapeEqual(a.Varied[i], b.Varied[i]) {
				return false
			}
		}
		return true
	}
	return false
}

func variedContains(v *Shape, x *Shape) bool {
	for _, c := range v.Varied {
		if shapeEqual(c, x) {
			return true
		}
		if c.Kind == KindVaried && variedContains(c, x) {
			return true
		}
	}
	return false
}

// remove from varied a all leaves contained in varied b
func variedRemove(a *Shape, b *Shape) *Shape {
	var kept []*Shape
	for _, c := range a.Varied {
		if c.Kind == KindVaried {
			r := variedRemove(c, b)
			if r != nil {
				kept = append(kept, r)
			}
		} else if !variedContains(b, c) {
			kept = append(kept, c)
		}
	}
	if len(kept) == 0 {
		return nil
	}
	if len(kept) == 1 {
		return kept[0]
	}
	return &Shape{Kind: KindVaried, Varied: kept}
}

func mergeShapes(a, b *Shape) *Shape {
	if shapeEqual(a, b) && a.Kind != KindUnknown {
		return a
	}
	if a.Kind == KindUnknown && b.Kind == KindUnknown {
		if verbose {
			logInfo("Missing type equality condition for unknown merge: [runner.Shape{Kind:\"unknown\", ScalarShape:(*runner.ScalarShape)(nil), ObjectShape:(*runner.ObjectShape)(nil), ArrayShape:(*runner.ArrayShape)(nil), VariedShape:(*runner.VariedShape)(nil)}] and [runner.Shape{Kind:\"unknown\", ScalarShape:(*runner.ScalarShape)(nil), ObjectShape:(*runner.ObjectShape)(nil), ArrayShape:(*runner.ArrayShape)(nil), VariedShape:(*runner.VariedShape)(nil)}].")
		}
		return &Shape{Kind: KindVaried, Varied: []*Shape{a, b}}
	}
	if a.Kind == KindObject && b.Kind == KindObject {
		obj := map[string]*Shape{}
		null := scalarShape("null")
		for k, av := range a.Object {
			if bv, ok := b.Object[k]; ok {
				obj[k] = mergeShapes(av, bv)
			} else {
				obj[k] = mergeShapes(av, null)
			}
		}
		for k, bv := range b.Object {
			if _, ok := a.Object[k]; !ok {
				obj[k] = mergeShapes(bv, null)
			}
		}
		return &Shape{Kind: KindObject, Object: obj}
	}
	if a.Kind == KindArray && b.Kind == KindArray {
		return mergeShapes(a.Array, b.Array)
	}
	if a.Kind == KindVaried && b.Kind == KindVaried {
		r := variedRemove(a, b)
		if r == nil {
			return b
		}
		return &Shape{Kind: KindVaried, Varied: []*Shape{b, r}}
	}
	if a.Kind == KindVaried {
		if variedContains(a, b) {
			return a
		}
		return &Shape{Kind: KindVaried, Varied: []*Shape{a, b}}
	}
	return &Shape{Kind: KindVaried, Varied: []*Shape{a, b}}
}

// top-level equality check: the original treats equal unknowns specially:
// at top-level of array merges, two unknowns are equal (reflect.DeepEqual)
func mergeTop(a, b *Shape) *Shape {
	return mergeShapes(a, b)
}

func sortedKeys(m map[string]*Shape) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func jsonString(s string) string {
	b, _ := json.Marshal(s)
	return string(b)
}

func writeShapeJSON(buf *bytes.Buffer, s *Shape, indent string) {
	in := indent + "  "
	buf.WriteString("{\n")
	buf.WriteString(in + "\"kind\": " + jsonString(s.Kind))
	switch s.Kind {
	case KindScalar:
		buf.WriteString(",\n" + in + "\"scalar\": " + jsonString(s.Scalar))
	case KindArray:
		buf.WriteString(",\n" + in + "\"array\": ")
		writeShapeJSON(buf, s.Array, in)
	case KindObject:
		buf.WriteString(",\n" + in + "\"object\": ")
		if len(s.Object) == 0 {
			buf.WriteString("{}")
		} else {
			buf.WriteString("{\n")
			keys := sortedKeys(s.Object)
			for i, k := range keys {
				buf.WriteString(in + "  " + jsonString(k) + ": ")
				writeShapeJSON(buf, s.Object[k], in+"  ")
				if i < len(keys)-1 {
					buf.WriteString(",")
				}
				buf.WriteString("\n")
			}
			buf.WriteString(in + "}")
		}
	case KindVaried:
		buf.WriteString(",\n" + in + "\"varied\": ")
		if len(s.Varied) == 0 {
			buf.WriteString("[]")
		} else {
			buf.WriteString("[\n")
			for i, c := range s.Varied {
				buf.WriteString(in + "  ")
				writeShapeJSON(buf, c, in+"  ")
				if i < len(s.Varied)-1 {
					buf.WriteString(",")
				}
				buf.WriteString("\n")
			}
			buf.WriteString(in + "]")
		}
	}
	buf.WriteString("\n" + indent + "}")
}

func ShapeJSON(s *Shape) string {
	var buf bytes.Buffer
	writeShapeJSON(&buf, s, "")
	return buf.String()
}

func prettyShapeLines(s *Shape) []string {
	switch s.Kind {
	case KindScalar:
		return []string{s.Scalar}
	case KindUnknown:
		return []string{"Unknown"}
	case KindArray:
		lines := []string{"Array of"}
		for _, l := range prettyShapeLines(s.Array) {
			lines = append(lines, "  "+l)
		}
		return lines
	case KindObject:
		lines := []string{"Object of"}
		for _, k := range sortedKeys(s.Object) {
			lines = append(lines, "  "+k+" of")
			for _, l := range prettyShapeLines(s.Object[k]) {
				lines = append(lines, "    "+l)
			}
		}
		return lines
	case KindVaried:
		lines := []string{"Varied of"}
		for i, c := range s.Varied {
			cl := prettyShapeLines(c)
			if i < len(s.Varied)-1 && len(cl) > 0 {
				cl[len(cl)-1] += " or"
			}
			for _, l := range cl {
				lines = append(lines, "  "+l)
			}
		}
		return lines
	}
	return nil
}

func PrettyShape(s *Shape) string {
	return strings.Join(prettyShapeLines(s), "\n")
}
