package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math"
	"regexp"
	"strconv"
	"strings"
)

// OrderedMap preserves insertion order of keys.
type OrderedMap struct {
	Keys   []string
	Values []interface{}
	idx    map[string]int
}

func NewOrderedMap() *OrderedMap {
	return &OrderedMap{idx: map[string]int{}}
}

func (m *OrderedMap) Set(k string, v interface{}) {
	if i, ok := m.idx[k]; ok {
		m.Values[i] = v
		return
	}
	m.idx[k] = len(m.Keys)
	m.Keys = append(m.Keys, k)
	m.Values = append(m.Values, v)
}

func (m *OrderedMap) Get(k string) (interface{}, bool) {
	if i, ok := m.idx[k]; ok {
		return m.Values[i], true
	}
	return nil, false
}

func (m *OrderedMap) Has(k string) bool {
	_, ok := m.idx[k]
	return ok
}

func (m *OrderedMap) Copy() *OrderedMap {
	n := &OrderedMap{Keys: append([]string{}, m.Keys...), Values: append([]interface{}{}, m.Values...), idx: map[string]int{}}
	for k, v := range m.idx {
		n.idx[k] = v
	}
	return n
}

// marshalValue encodes a value as Go's encoding/json would.
func marshalValue(v interface{}) ([]byte, error) {
	switch t := v.(type) {
	case *OrderedMap:
		var buf bytes.Buffer
		if err := writeRowJSON(&buf, t); err != nil {
			return nil, err
		}
		return buf.Bytes(), nil
	}
	return json.Marshal(v)
}

func writeRowJSON(buf *bytes.Buffer, m *OrderedMap) error {
	buf.WriteByte('{')
	for i, k := range m.Keys {
		if i > 0 {
			buf.WriteByte(',')
		}
		buf.WriteString(strconv.QuoteToASCII(k))
		buf.WriteByte(':')
		b, err := marshalValue(m.Values[i])
		if err != nil {
			return err
		}
		buf.Write(b)
	}
	buf.WriteByte('}')
	return nil
}

// RowsWriter writes JSON array of rows in dsq's style.
type RowsWriter struct {
	buf   bytes.Buffer
	count int
}

func NewRowsWriter() *RowsWriter {
	w := &RowsWriter{}
	w.buf.WriteByte('[')
	return w
}

func (w *RowsWriter) sep() {
	if w.count > 0 {
		w.buf.WriteString(",\n")
	}
	w.count++
}

