func inRanges(r rune, rs []runeRange) bool {
	lo, hi := 0, len(rs)-1
	for lo <= hi {
		m := (lo + hi) / 2
		if r < rs[m].lo {
			hi = m - 1
		} else if r > rs[m].hi {
			lo = m + 1
		} else {
			return true
		}
	}
	return false
}

func runeWidth(r rune) int {
	if r < 0 || r > 0x10FFFF {
		return 0
	}
	if r < 0x20 {
		return 0
	}
	if r < 0x7F {
		return 1
	}
	if inRanges(r, nonprintRanges) {
		return 0
	}
	if unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Me, r) {
		return 0
	}
	if inRanges(r, doubleWidthRanges) {
		return 2
	}
	return 1
}

func stringWidth(s string) int {
	w := 0
	for _, r := range s {
		w += runeWidth(r)
	}
	return w
}
