var verbose bool

func logInfo(format string, args ...interface{}) {
	if !verbose {
		return
	}
	msg := format
	if len(args) > 0 {
		msg = fmt.Sprintf(format, args...)
	}
	fmt.Fprintf(os.Stderr, "[INFO] %s %s\n", time.Now().Format("2006-01-02T15:04:05"), msg)
