// exitError carries an exit code.
type exitError struct {
	code int
	msg  string
}

func (e *exitError) Error() string { return e.msg }

// DSError mimics DataStation errors.
type DSError struct {
	Name    string
	Message string
}

func (e *DSError) Error() string {
	b, _ := json.Marshal(e.Message)
	return "DSError {\n  \"name\": \"" + e.Name + "\",\n  \"message\": " + string(b) + ",\n  \"stack\": \"\",\n  \"targetPanelId\": \"\",\n  \"extra\": null\n}"
}

func userError(msg string) error {
	return &DSError{Name: "UserError", Message: msg}
}

func exceptionError(err error) error {
	if _, ok := err.(*DSError); ok {
		return err
	}
	return &DSError{Name: "Error", Message: err.Error()}
}

// panicError mimics Go runtime panics (exit code 2).
type panicError struct {
	msg string
}

func (e *panicError) Error() string { return e.msg }

func nilPanic() error {
	return &panicError{msg: "panic: runtime error: invalid memory address or nil pointer dereference\n[signal SIGSEGV: segmentation violation code=0x1 addr=0x0 pc=0x0]\n\ngoroutine 1 [running]:\nmain.dumpJSONFile()"}
}

func indexPanic(i, n int) error {
	return &panicError{msg: fmt.Sprintf("panic: runtime error: index out of range [%d] with length %d\n\ngoroutine 1 [running]:", i, n)}
}

func main() {
	code := run(os.Args[1:])
	os.Exit(code)
}

func reportError(err error) int {
	switch t := err.(type) {
	case *panicError:
		fmt.Fprintln(os.Stderr, t.msg)
		return 2
	case *exitError:
		if t.msg != "" {
			fmt.Fprintln(os.Stderr, t.msg)
		}
		return t.code
	}
	fmt.Fprintln(os.Stderr, err.Error())
	return 1
}

