func lastArgIsQuery(s string) bool {
	if strings.Contains(s, " ") {
		return true
	}
	if mimeFromName(s) == "" {
		return false
	}
	if _, err := os.Stat(s); err == nil {
		return true
	}
	return false
}

func dumpResult(raw []byte, pretty bool) error {
	if !pretty {
		os.Stdout.Write(raw)
		os.Stdout.Write([]byte("\n"))
		return nil
	}
	out, err := prettyRender(raw)
	if err != nil {
		return err
	}
	os.Stdout.WriteString(out)
	return nil
}

func prettyRender(raw []byte) (string, error) {
	v, err := parseJSONValue(raw)
	if err != nil {
		return "", exceptionError(err)
	}
	s := GetShape(v)
	if s.Kind != KindArray || s.Array == nil || s.Array.Kind != KindObject {
		return "", nilPanic()
	}
	cols := sortedKeys(s.Array.Object)
	arr, _ := v.([]interface{})
	var rows [][]string
	for _, r := range arr {
		m, _ := r.(map[string]interface{})
		row := make([]string, len(cols))
		for i, c := range cols {
			var val interface{}
			if m != nil {
				val = m[c]
			}
			row[i] = prettyValue(val)
		}
		rows = append(rows, row)
	}
	out := renderTable(cols, rows)
	if len(arr) == 1 {
		out += "(1 row)\n"
	} else {
		out += fmt.Sprintf("(%d rows)\n", len(arr))
	}
	return out, nil
}

func parseJSONValue(raw []byte) (interface{}, error) {
	dec := json.NewDecoder(bytes.NewReader(raw))
	var v interface{}
	if err := dec.Decode(&v); err != nil {
		return nil, err
	}
	return v, nil
}

func shapeFromRaw(raw []byte) (*Shape, error) {
	v, err := parseJSONValue(raw)
	if err != nil {
		return nil, err
	}
	return GetShape(v), nil
}

