var refRe = regexp.MustCompile(`\{(?:(\d+)(?:,\s*("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'))?|("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'))?\}`)

type tableRef struct {
	idx  int
	path string
}

func (c *queryContext) rewrite(query string) (string, []tableRef, error) {
	var refs []tableRef
	var rerr error
	out := refRe.ReplaceAllStringFunc(query, func(m string) string {
		if rerr != nil {
			return m
		}
		sm := refRe.FindStringSubmatch(m)
		idx := 0
		path := ""
		if sm[1] != "" {
			n, err := strconv.Atoi(sm[1])
			if err != nil {
				n = -1
			}
			idx = n
			if sm[2] != "" {
				path = sm[2][1 : len(sm[2])-1]
			}
		} else if sm[3] != "" {
			path = sm[3][1 : len(sm[3])-1]
		}
		if c.fastPath {
			if sm[1] != "" && strconv.Itoa(idx) != sm[1] {
				return `""`
			}
			if idx < 0 || idx >= len(c.inputs) {
				return `""`
			}
			if path != "" {
				rerr = userError("Path enters non-object: " + path)
				return m
			}
			return `"t_` + strconv.Itoa(idx) + `"`
		}
		if idx < 0 || idx >= len(c.inputs) {
			rerr = indexPanic(idx, len(c.inputs))
			return m
		}
		// validate path against shape
		if path != "" {
			s, err := c.inputs[idx].imp.TableShape()
			if err != nil {
				rerr = err
				return m
			}
			if _, err := shapeAtPath(s, path); err != nil {
				rerr = err
				return m
			}
		}
		refs = append(refs, tableRef{idx: idx, path: path})
		return `"t_` + strconv.Itoa(idx) + `"`
	})
	if rerr != nil {
		return "", nil, rerr
	}
	return out, refs, nil
}

func splitPath(path string) []string {
	var parts []string
	var cur strings.Builder
	for i := 0; i < len(path); i++ {
		ch := path[i]
		if ch == '\\' && i+1 < len(path) && path[i+1] == '.' {
			cur.WriteByte('.')
			i++
			continue
		}
		if ch == '.' {
			parts = append(parts, cur.String())
			cur.Reset()
			continue
		}
		cur.WriteByte(ch)
	}
	parts = append(parts, cur.String())
	return parts
}

func shapeAtPath(s *Shape, path string) (*Shape, error) {
	if path == "" {
		return s, nil
	}
	for _, part := range splitPath(path) {
		if s.Kind != KindObject {
			return nil, userError("Path enters non-object: " + path)
		}
		c, ok := s.Object[part]
		if !ok {
			return nil, userError("Path does not exist: " + part)
		}
		s = c
	}
	return s, nil
}

func valueAtPath(v interface{}, path string) interface{} {
	if path == "" {
		return v
	}
	for _, part := range splitPath(path) {
		m, ok := v.(map[string]interface{})
		if !ok {
			return nil
		}
		v = m[part]
	}
	return v
}

func (c *queryContext) runQuery(query string) ([]byte, error) {
	q, refs, err := c.rewrite(query)
	if err != nil {
		return nil, err
	}
	if !c.fastPath && !c.cacheValid {
		// last path wins per table index; import in order of first reference
		order := []int{}
		paths := map[int]string{}
		for _, r := range refs {
			if _, ok := paths[r.idx]; !ok {
				order = append(order, r.idx)
			}
			paths[r.idx] = r.path
		}
		for _, idx := range order {
			logInfo("Creating table t_%d", idx)
			if err := importJSONTable(c.db, c.inputs[idx], idx, paths[idx]); err != nil {
				return nil, err
			}
		}
	}
	return execQuery(c.db, q)
}

func execQuery(db *DB, q string) ([]byte, error) {
	for {
		st, err := db.Prepare(q)
		if err != nil {
			return nil, err
		}
		if st.tail != "" {
			st.Finalize()
			q = st.tail
			continue
		}
		defer st.Finalize()
		w := NewRowsWriter()
		ncol := st.ColumnCount()
		names := make([]string, ncol)
		decl := make([]string, ncol)
		for i := 0; i < ncol; i++ {
			names[i] = st.ColumnName(i)
			decl[i] = st.ColumnDecltype(i)
		}
		for {
			ok, err := st.Step()
			if err != nil {
				return nil, err
			}
			if !ok {
				break
			}
			row := NewOrderedMap()
			for i := 0; i < ncol; i++ {
				v := st.Column(i)
				v = convertColumnValue(v, decl[i])
				row.Set(names[i], v)
			}
			if err := w.WriteRow(row); err != nil {
				return nil, err
			}
		}
		return w.Bytes(), nil
	}
}

