}

func convertColumnValue(v interface{}, decl string) interface{} {
	switch t := v.(type) {
	case int64:
		switch decl {
		case "boolean":
			return t > 0
		case "date", "datetime", "timestamp":
			var tm time.Time
			if t > 1e12 || t < -1e12 {
				tm = time.Unix(0, t*int64(time.Millisecond))
			} else {
				tm = time.Unix(t, 0)
			}
			return tm.UTC()
		}
		return t
	case string:
		switch decl {
		case "date", "datetime", "timestamp":
			s := strings.TrimSuffix(t, "Z")
			for _, f := range sqliteTimestampFormats {
				if tv, err := time.ParseInLocation(f, s, time.UTC); err == nil {
					return tv
				}
			}
			return time.Time{}
		}
		return t
	case []byte:
		return string(t)
	}
	return v
}

// ---------------- JSON path table import ----------------

type column struct {
	name string
	typ  string
}

func escapeDots(s string) string {
	return strings.ReplaceAll(s, ".", "\\.")
}

func flattenColumns(obj map[string]*Shape, prefix string, out *[]column) {
	for _, k := range sortedKeys(obj) {
		s := obj[k]
		if s.Kind == KindObject {
			flattenColumns(s.Object, prefix+escapeDots(k)+".", out)
			continue
		}
		*out = append(*out, column{name: prefix + k, typ: sqlTypeForShape(s)})
	}
}

func sqlTypeForShape(s *Shape) string {
	kind := ""
	if s.Kind == KindVaried && len(s.Varied) == 2 {
		for _, c := range s.Varied {
			if c.Kind == KindScalar {
				if c.Scalar == "null" {
					continue
				}
				if kind != "" && kind != c.Scalar {
					kind = ""
					break
				}
				kind = c.Scalar
			} else {
				kind = ""
				break
			}
		}
	}
	if s.Kind == KindScalar {
		kind = s.Scalar
	}
	switch kind {
	case "number":
		return "REAL"
	case "boolean":
		return "BOOLEAN"
	}
	return "TEXT"
}

func quoteIdent(s string) string {
	return `"` + strings.ReplaceAll(s, `"`, `""`) + `"`
}

func lookupColumn(row map[string]interface{}, col string) interface{} {
	if v, ok := row[col]; ok {
		return v
	}
	var cur interface{} = row
	for _, part := range splitPath(col) {
		m, ok := cur.(map[string]interface{})
		if !ok {
			return nil
		}
		cur = m[part]
	}
	return cur
}

func bindableValue(v interface{}) (interface{}, error) {
	switch t := v.(type) {
	case nil, string, float64, bool, int64:
		return t, nil
	case map[string]interface{}, []interface{}:
		b, err := json.Marshal(t)
		if err != nil {
			return nil, err
		}
		return b, nil
	}
	b, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	return b, nil
}

func importJSONTable(db *DB, in *inputFile, idx int, path string) error {
	s, err := in.imp.TableShape()
	if err != nil {
		return err
	}
	s, err = shapeAtPath(s, path)
	if err != nil {
		return err
	}
	if s.Kind != KindArray || s.Array == nil || s.Array.Kind != KindObject {
		return fmt.Errorf("Input is not an array of objects: %s.", in.name)
	}
	var cols []column
	flattenColumns(s.Array.Object, "", &cols)
	sort.SliceStable(cols, func(i, j int) bool { return cols[i].name < cols[j].name })
	table := "t_" + strconv.Itoa(idx)
	var defs []string
	for _, c := range cols {
		defs = append(defs, quoteIdent(c.name)+" "+c.typ)
	}
	create := "CREATE TABLE " + quoteIdent(table) + " (" + strings.Join(defs, ", ") + ")"
	if err := db.Exec(create); err != nil {
		return err
	}
	v, err := in.imp.Value()
	if err != nil {
		return exceptionError(err)
	}
	v = valueAtPath(v, path)
	arr, _ := v.([]interface{})
	if len(arr) == 0 {
		return nil
	}
	placeholders := make([]string, len(cols))
	for i := range placeholders {
		placeholders[i] = "?"
	}
	if err := db.Exec("BEGIN"); err != nil {
		return err
	}
	st, err := db.Prepare("INSERT INTO " + quoteIdent(table) + " VALUES (" + strings.Join(placeholders, ", ") + ")")
	if err != nil {
		db.Exec("ROLLBACK")
		return err
	}
	for _, r := range arr {
		row, _ := r.(map[string]interface{})
		for i, c := range cols {
			var val interface{}
			if row != nil {
				val = lookupColumn(row, c.name)
			}
			bv, err := bindableValue(val)
			if err != nil {
				st.Finalize()
				return err
			}
			if err := st.Bind(i+1, bv); err != nil {
				st.Finalize()
				return err
			}
		}
		if _, err := st.Step(); err != nil {
			st.Finalize()
			return err
		}
		st.Reset()
	}
	st.Finalize()
	return db.Exec("COMMIT")
}

// ---------------- interactive ----------------

func (c *queryContext) repl() int {
	reader := bufio.NewReader(os.Stdin)
	tty := isTerminal(os.Stdin)
	for {
		if tty {
			fmt.Fprint(os.Stdout, "dsq> ")
		}
		line, err := reader.ReadString('\n')
		if err != nil && line == "" {
			if errors.Is(err, io.EOF) {
				fmt.Fprintln(os.Stderr, "EOF")
				return 1
			}
			return reportError(err)
		}
		line = strings.TrimRight(line, "\r\n")
		if strings.TrimSpace(line) == "" {
			if err != nil {
				fmt.Fprintln(os.Stderr, "EOF")
				return 1
			}
			continue
		}
		raw, qerr := c.runQuery(line)
		if qerr != nil {
			return reportError(qerr)
		}
		if c.opts.schema {
			s, serr := shapeFromRaw(raw)
			if serr != nil {
				return reportError(exceptionError(serr))
			}
			fmt.Println(PrettyShape(s))
		} else {
			if derr := dumpResult(raw, true); derr != nil {
				return reportError(derr)
			}
		}
		if err != nil {
			fmt.Fprintln(os.Stderr, "EOF")
			return 1
		}
	}
}
EOF
echo ok"}

