cd /workspace && cat > main.go <<'EOF'
package main

import (
	"bufio"
	"bytes"
	"crypto/sha1"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math/rand"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
)

var verbose bool

func logInfo(format string, args ...interface{}) {
	if !verbose {
		return
	}
	msg := format
	if len(args) > 0 {
		msg = fmt.Sprintf(format, args...)
	}
	fmt.Fprintf(os.Stderr, "[INFO] %s %s\n", time.Now().Format("2006-01-02T15:04:05"), msg)
}

// exitError carries an exit code.
type exitError struct {
	code int
	msg  string
}

func (e *exitError) Error() string { return e.msg }

// DSError mimics DataStation errors.
type DSError struct {
	Name    string
	Message string
}

func (e *DSError) Error() string {
	b, _ := json.Marshal(e.Message)
	return "DSError {\n  \"name\": \"" + e.Name + "\",\n  \"message\": " + string(b) + ",\n  \"stack\": \"\",\n  \"targetPanelId\": \"\",\n  \"extra\": null\n}"
}

func userError(msg string) error {
	return &DSError{Name: "UserError", Message: msg}
}

func exceptionError(err error) error {
	if _, ok := err.(*DSError); ok {
		return err
	}
	return &DSError{Name: "Error", Message: err.Error()}
}

// panicError mimics Go runtime panics (exit code 2).
type panicError struct {
	msg string
}

func (e *panicError) Error() string { return e.msg }

func nilPanic() error {
	return &panicError{msg: "panic: runtime error: invalid memory address or nil pointer dereference\n[signal SIGSEGV: segmentation violation code=0x1 addr=0x0 pc=0x0]\n\ngoroutine 1 [running]:\nmain.dumpJSONFile()"}
}

func indexPanic(i, n int) error {
	return &panicError{msg: fmt.Sprintf("panic: runtime error: index out of range [%d] with length %d\n\ngoroutine 1 [running]:", i, n)}
}

func main() {
	code := run(os.Args[1:])
	os.Exit(code)
}

func reportError(err error) int {
	switch t := err.(type) {
	case *panicError:
		fmt.Fprintln(os.Stderr, t.msg)
		return 2
	case *exitError:
		if t.msg != "" {
			fmt.Fprintln(os.Stderr, t.msg)
		}
		return t.code
	}
	fmt.Fprintln(os.Stderr, err.Error())
	return 1
}

type options struct {
	pretty         bool
	schema         bool
	cache          bool
	dumpCacheFile  bool
	interactive    bool
	convertNumbers bool
	stdinType      string
	sqlFile        string
}

type inputFile struct {
	name string
	mime string
	imp  *Imported
}

func isTerminal(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return fi.Mode()&os.ModeCharDevice != 0
}

func run(args []string) int {
	var opts options
	var nonFlag []string
	stdinSet := false
	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-h", "--help":
			fmt.Fprint(os.Stderr, helpText)
			return 0
		case "-v", "--version":
			fmt.Fprintln(os.Stderr, "dsq latest")
			return 0
		case "-p", "--pretty":
			opts.pretty = true
		case "-s", "--stdin":
			if i+1 >= len(args) {
				fmt.Fprintln(os.Stderr, "Must specify stdin mimetype.")
				return 1
			}
			opts.stdinType = args[i+1]
			stdinSet = true
			i++
		case "-f", "--file":
			if i+1 >= len(args) {
				fmt.Fprintln(os.Stderr, "Must specify a SQL file.")
				return 1
			}
			opts.sqlFile = args[i+1]
			i++
		case "-c", "--schema":
			opts.schema = true
		case "-C", "--cache":
			opts.cache = true
		case "-D", "--cache-file":
			opts.dumpCacheFile = true
		case "-i", "--interactive":
			opts.interactive = true
		case "-n", "--convert-numbers":
			opts.convertNumbers = true
		case "--verbose":
			verbose = true
		default:
			nonFlag = append(nonFlag, arg)
		}
	}

	var files []string
	stdinMime := ""
	if stdinSet {
		data, _ := io.ReadAll(os.Stdin)
		tmp := filepath.Join(os.TempDir(), "dsq-stdin"+strconv.FormatUint(uint64(rand.New(rand.NewSource(time.Now().UnixNano())).Uint32()), 10))
		if err := os.WriteFile(tmp, data, 0644); err != nil {
			return reportError(err)
		}
		defer os.Remove(tmp)
		files = append(files, tmp)
		stdinMime = resolveStdinMime(opts.stdinType)
	}
	files = append(files, nonFlag...)

	if len(files) == 0 {
		fmt.Fprintln(os.Stderr, "No input files.")
		return 1
	}

	query := ""
	hasQuery := false
	if opts.sqlFile != "" {
		b, err := os.ReadFile(opts.sqlFile)
		if err != nil {
			fmt.Fprintln(os.Stderr, "Error opening sql file: "+err.Error())
			return 1
		}
		query = string(b)
		hasQuery = true
	} else if len(files) > 1 {
		last := files[len(files)-1]
		if lastArgIsQuery(last) {
			query = last
			hasQuery = true
			files = files[:len(files)-1]
		}
	}

	var inputs []*inputFile
	for i, f := range files {
		in := &inputFile{name: f}
		if stdinSet && i == 0 {
			in.mime = stdinMime
		} else {
			in.mime = mimeFromName(f)
		}
		inputs = append(inputs, in)
	}

	cacheMode := opts.cache || opts.interactive || opts.dumpCacheFile
	cachePath := ""
	cacheValid := false
	if cacheMode {
		h := sha1.New()
		for _, in := range inputs {
			fh, err := os.Open(in.name)
			if err != nil {
				return reportError(err)
			}
			io.Copy(h, fh)
			fh.Close()
		}
		cachePath = filepath.Join(os.TempDir(), "dsq-cache-"+hex.EncodeToString(h.Sum(nil))+".db")
		if _, err := os.Stat(cachePath); err == nil {
			cacheValid = true
		} else {
			fmt.Fprintln(os.Stderr, "Cache invalid, re-import required.")
		}
		if opts.dumpCacheFile {
			fmt.Println(cachePath)
			return 0
		}
	}

	allCSV := true
	for _, in := range inputs {
		if in.mime != mimeCSV && in.mime != mimeTSV {
			allCSV = false
		}
	}

	for _, in := range inputs {
		if in.mime == "" {
			fmt.Fprintf(os.Stderr, "Unknown mimetype for file: %s.\n", in.name)
			return 1
		}
		logInfo("Assumed '%s' from '%s' given '%s' when loading file", in.mime, in.mime, in.name)
		imp, err := importFile(in.name, in.mime, opts.convertNumbers)
		if err != nil {
			return reportError(err)
		}
		in.imp = imp
	}

	if !hasQuery && !opts.interactive {
		imp := inputs[0].imp
		if opts.schema {
			s, err := imp.FileShape()
			if err != nil {
				return reportError(err)
			}
			if opts.pretty {
				fmt.Println(PrettyShape(s))
			} else {
				fmt.Println(ShapeJSON(s))
			}
			return 0
		}
		if err := dumpResult(imp.Raw, opts.pretty); err != nil {
			return reportError(err)
		}
		return 0
	}

	dbPath := ":memory:"
	if cacheMode {
		dbPath = cachePath
	}
	db, err := openDB(dbPath)
	if err != nil {
		return reportError(err)
	}
	defer db.Close()

	ctx := &queryContext{db: db, inputs: inputs, opts: opts, cacheValid: cacheValid, fastPath: allCSV}
	if allCSV && (!cacheValid || opts.interactive) {
		for i, in := range inputs {
			if err := importCSVFast(db, in, i, opts.convertNumbers); err != nil {
				return reportError(err)
			}
		}
	}

	if opts.interactive {
		return ctx.repl()
	}

	raw, err := ctx.runQuery(query)
	if err != nil {
		return reportError(err)
	}
	if opts.schema {
		s, err := shapeFromRaw(raw)
		if err != nil {
			return reportError(exceptionError(err))
		}
		if opts.pretty {
			fmt.Println(PrettyShape(s))
		} else {
			fmt.Println(ShapeJSON(s))
		}
		return 0
	}
	if err := dumpResult(raw, opts.pretty); err != nil {
		return reportError(err)
	}
	return 0
}

func lastArgIsQuery(s string) bool {
	if strings.Contains(s, " ") {
		return true
	}
	if mimeFromName(s) == "" {
		return false
	}
	if _, err := os.Stat(s); err == nil {
		return true
	}
	return false
}

func dumpResult(raw []byte, pretty bool) error {
	if !pretty {
		os.Stdout.Write(raw)
		os.Stdout.Write([]byte("\n"))
		return nil
	}
	out, err := prettyRender(raw)
	if err != nil {
		return err
	}
	os.Stdout.WriteString(out)
	return nil
}

func prettyRender(raw []byte) (string, error) {
	v, err := parseJSONValue(raw)
	if err != nil {
		return "", exceptionError(err)
	}
	s := GetShape(v)
	if s.Kind != KindArray || s.Array == nil || s.Array.Kind != KindObject {
		return "", nilPanic()
	}
	cols := sortedKeys(s.Array.Object)
	arr, _ := v.([]interface{})
	var rows [][]string
	for _, r := range arr {
		m, _ := r.(map[string]interface{})
		row := make([]string, len(cols))
		for i, c := range cols {
			var val interface{}
			if m != nil {
				val = m[c]
			}
			row[i] = prettyValue(val)
		}
		rows = append(rows, row)
	}
	out := renderTable(cols, rows)
	if len(arr) == 1 {
		out += "(1 row)\n"
	} else {
		out += fmt.Sprintf("(%d rows)\n", len(arr))
	}
	return out, nil
}

func parseJSONValue(raw []byte) (interface{}, error) {
	dec := json.NewDecoder(bytes.NewReader(raw))
	var v interface{}
	if err := dec.Decode(&v); err != nil {
		return nil, err
	}
	return v, nil
}

func shapeFromRaw(raw []byte) (*Shape, error) {
	v, err := parseJSONValue(raw)
	if err != nil {
		return nil, err
	}
	return GetShape(v), nil
}

// ---------------- query handling ----------------

type queryContext struct {
	db         *DB
	inputs     []*inputFile
	opts       options
	cacheValid bool
	fastPath   bool
}

var refRe = regexp.MustCompile(`\{(?:(\d+)(?:,\s*("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'))?|("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'))?\}`)

type tableRef struct {
	idx  int
	path string
}

func (c *queryContext) rewrite(query string) (string, []tableRef, error) {
	var refs []tableRef
	var rerr error
	out := refRe.ReplaceAllStringFunc(query, func(m string) string {
		if rerr != nil {
			return m
		}
		sm := refRe.FindStringSubmatch(m)
		idx := 0
		path := ""
		if sm[1] != "" {
			n, err := strconv.Atoi(sm[1])
			if err != nil {
				n = -1
			}
			idx = n
			if sm[2] != "" {
				path = sm[2][1 : len(sm[2])-1]
			}
		} else if sm[3] != "" {
			path = sm[3][1 : len(sm[3])-1]
		}
		if c.fastPath {
			if sm[1] != "" && strconv.Itoa(idx) != sm[1] {
				return `""`
			}
			if idx < 0 || idx >= len(c.inputs) {
				return `""`
			}
			if path != "" {
				rerr = userError("Path enters non-object: " + path)
				return m
			}
			return `"t_` + strconv.Itoa(idx) + `"`
		}
		if idx < 0 || idx >= len(c.inputs) {
			rerr = indexPanic(idx, len(c.inputs))
			return m
		}
		// validate path against shape
		if path != "" {
			s, err := c.inputs[idx].imp.TableShape()
			if err != nil {
				rerr = err
				return m
			}
			if _, err := shapeAtPath(s, path); err != nil {
				rerr = err
				return m
			}
		}
		refs = append(refs, tableRef{idx: idx, path: path})
		return `"t_` + strconv.Itoa(idx) + `"`
	})
	if rerr != nil {
		return "", nil, rerr
	}
	return out, refs, nil
}

func splitPath(path string) []string {
	var parts []string
	var cur strings.Builder
	for i := 0; i < len(path); i++ {
		ch := path[i]
		if ch == '\\' && i+1 < len(path) && path[i+1] == '.' {
			cur.WriteByte('.')
			i++
			continue
		}
		if ch == '.' {
			parts = append(parts, cur.String())
			cur.Reset()
			continue
		}
		cur.WriteByte(ch)
	}
	parts = append(parts, cur.String())
	return parts
}

func shapeAtPath(s *Shape, path string) (*Shape, error) {
	if path == "" {
		return s, nil
	}
	for _, part := range splitPath(path) {
		if s.Kind != KindObject {
			return nil, userError("Path enters non-object: " + path)
		}
		c, ok := s.Object[part]
		if !ok {
			return nil, userError("Path does not exist: " + part)
		}
		s = c
	}
	return s, nil
}

func valueAtPath(v interface{}, path string) interface{} {
	if path == "" {
		return v
	}
	for _, part := range splitPath(path) {
		m, ok := v.(map[string]interface{})
		if !ok {
			return nil
		}
		v = m[part]
	}
	return v
}

func (c *queryContext) runQuery(query string) ([]byte, error) {
	q, refs, err := c.rewrite(query)
	if err != nil {
		return nil, err
	}
	if !c.fastPath && !c.cacheValid {
		// last path wins per table index; import in order of first reference
		order := []int{}
		paths := map[int]string{}
		for _, r := range refs {
			if _, ok := paths[r.idx]; !ok {
				order = append(order, r.idx)
			}
			paths[r.idx] = r.path
		}
		for _, idx := range order {
			logInfo("Creating table t_%d", idx)
			if err := importJSONTable(c.db, c.inputs[idx], idx, paths[idx]); err != nil {
				return nil, err
			}
		}
	}
	return execQuery(c.db, q)
}

func execQuery(db *DB, q string) ([]byte, error) {
	for {
		st, err := db.Prepare(q)
		if err != nil {
			return nil, err
		}
		if st.tail != "" {
			st.Finalize()
			q = st.tail
			continue
		}
		defer st.Finalize()
		w := NewRowsWriter()
		ncol := st.ColumnCount()
		names := make([]string, ncol)
		decl := make([]string, ncol)
		for i := 0; i < ncol; i++ {
			names[i] = st.ColumnName(i)
			decl[i] = st.ColumnDecltype(i)
		}
		for {
			ok, err := st.Step()
			if err != nil {
				return nil, err
			}
			if !ok {
				break
			}
			row := NewOrderedMap()
			for i := 0; i < ncol; i++ {
				v := st.Column(i)
				v = convertColumnValue(v, decl[i])
				row.Set(names[i], v)
			}
			if err := w.WriteRow(row); err != nil {
				return nil, err
			}
		}
		return w.Bytes(), nil
	}
}

var sqliteTimestampFormats = []string{
	"2006-01-02 15:04:05.999999999-07:00",
	"2006-01-02T15:04:05.999999999-07:00",
	"2006-01-02 15:04:05.999999999",
	"2006-01-02T15:04:05.999999999",
	"2006-01-02 15:04:05",
	"2006-01-02T15:04:05",
	"2006-01-02 15:04",
	"2006-01-02T15:04",
	"2006-01-02",
}

func convertColumnValue(v interface{}, decl string) interface{} {
	switch t := v.(type) {
	case int64:
		switch decl {
		case "boolean":
			return t > 0
		case "date", "datetime", "timestamp":
			var tm time.Time
			if t > 1e12 || t < -1e12 {
				tm = time.Unix(0, t*int64(time.Millisecond))
			} else {
				tm = time.Unix(t, 0)
			}
			return tm.UTC()
		}
		return t
	case string:
		switch decl {
		case "date", "datetime", "timestamp":
			s := strings.TrimSuffix(t, "Z")
			for _, f := range sqliteTimestampFormats {
				if tv, err := time.ParseInLocation(f, s, time.UTC); err == nil {
					return tv
				}
			}
			return time.Time{}
		}
		return t
	case []byte:
		return string(t)
	}
	return v
}

// ---------------- JSON path table import ----------------

type column struct {
	name string
	typ  string
}

func escapeDots(s string) string {
	return strings.ReplaceAll(s, ".", "\\.")
}

func flattenColumns(obj map[string]*Shape, prefix string, out *[]column) {
	for _, k := range sortedKeys(obj) {
		s := obj[k]
		if s.Kind == KindObject {
			flattenColumns(s.Object, prefix+escapeDots(k)+".", out)
			continue
		}
		*out = append(*out, column{name: prefix + k, typ: sqlTypeForShape(s)})
	}
}

func sqlTypeForShape(s *Shape) string {
	kind := ""
	if s.Kind == KindVaried && len(s.Varied) == 2 {
		for _, c := range s.Varied {
			if c.Kind == KindScalar {
				if c.Scalar == "null" {
					continue
				}
				if kind != "" && kind != c.Scalar {
					kind = ""
					break
				}
				kind = c.Scalar
			} else {
				kind = ""
				break
			}
		}
	}
	if s.Kind == KindScalar {
		kind = s.Scalar
	}
	switch kind {
	case "number":
		return "REAL"
	case "boolean":
		return "BOOLEAN"
	}
	return "TEXT"
}

func quoteIdent(s string) string {
	return `"` + strings.ReplaceAll(s, `"`, `""`) + `"`
}

func lookupColumn(row map[string]interface{}, col string) interface{} {
	if v, ok := row[col]; ok {
		return v
	}
	var cur interface{} = row
	for _, part := range splitPath(col) {
		m, ok := cur.(map[string]interface{})
		if !ok {
			return nil
		}
		cur = m[part]
	}
	return cur
}

func bindableValue(v interface{}) (interface{}, error) {
	switch t := v.(type) {
	case nil, string, float64, bool, int64:
		return t, nil
	case map[string]interface{}, []interface{}:
		b, err := json.Marshal(t)
		if err != nil {
			return nil, err
		}
		return b, nil
	}
	b, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	return b, nil
}

func importJSONTable(db *DB, in *inputFile, idx int, path string) error {
	s, err := in.imp.TableShape()
	if err != nil {
		return err
	}
	s, err = shapeAtPath(s, path)
	if err != nil {
		return err
	}
	if s.Kind != KindArray || s.Array == nil || s.Array.Kind != KindObject {
		return fmt.Errorf("Input is not an array of objects: %s.", in.name)
	}
	var cols []column
	flattenColumns(s.Array.Object, "", &cols)
	sort.SliceStable(cols, func(i, j int) bool { return cols[i].name < cols[j].name })
	table := "t_" + strconv.Itoa(idx)
	var defs []string
	for _, c := range cols {
		defs = append(defs, quoteIdent(c.name)+" "+c.typ)
	}
	create := "CREATE TABLE " + quoteIdent(table) + " (" + strings.Join(defs, ", ") + ")"
	if err := db.Exec(create); err != nil {
		return err
	}
	v, err := in.imp.Value()
	if err != nil {
		return exceptionError(err)
	}
	v = valueAtPath(v, path)
	arr, _ := v.([]interface{})
	if len(arr) == 0 {
		return nil
	}
	placeholders := make([]string, len(cols))
	for i := range placeholders {
		placeholders[i] = "?"
	}
	if err := db.Exec("BEGIN"); err != nil {
		return err
	}
	st, err := db.Prepare("INSERT INTO " + quoteIdent(table) + " VALUES (" + strings.Join(placeholders, ", ") + ")")
	if err != nil {
		db.Exec("ROLLBACK")
		return err
	}
	for _, r := range arr {
		row, _ := r.(map[string]interface{})
		for i, c := range cols {
			var val interface{}
			if row != nil {
				val = lookupColumn(row, c.name)
			}
			bv, err := bindableValue(val)
			if err != nil {
				st.Finalize()
				return err
			}
			if err := st.Bind(i+1, bv); err != nil {
				st.Finalize()
				return err
			}
		}
		if _, err := st.Step(); err != nil {
			st.Finalize()
			return err
		}
		st.Reset()
	}
	st.Finalize()
	return db.Exec("COMMIT")
}

// ---------------- interactive ----------------

func (c *queryContext) repl() int {
	reader := bufio.NewReader(os.Stdin)
	tty := isTerminal(os.Stdin)
	for {
		if tty {
			fmt.Fprint(os.Stdout, "dsq> ")
		}
		line, err := reader.ReadString('\n')
		if err != nil && line == "" {
			if errors.Is(err, io.EOF) {
				fmt.Fprintln(os.Stderr, "EOF")
				return 1
			}
			return reportError(err)
		}
		line = strings.TrimRight(line, "\r\n")
		if strings.TrimSpace(line) == "" {
			if err != nil {
				fmt.Fprintln(os.Stderr, "EOF")
				return 1
			}
			continue
		}
		raw, qerr := c.runQuery(line)
		if qerr != nil {
			return reportError(qerr)
		}
		if c.opts.schema {
			s, serr := shapeFromRaw(raw)
			if serr != nil {
				return reportError(exceptionError(serr))
			}
			fmt.Println(PrettyShape(s))
		} else {
			if derr := dumpResult(raw, true); derr != nil {
				return reportError(derr)
			}
		}
		if err != nil {
			fmt.Fprintln(os.Stderr, "EOF")
			return 1
		}
	}
}
EOF
echo ok

