	case mimeText, mimeSyslog3164, mimeSyslog5424:
		return importText(name)
	case mimeLogfmt:
		return importLogfmt(name)
	case mimeParquet:
		return importParquet(name)
	case mimeORC:
		return importORC(name)
	case mimeAvro:
		return importAvro(name)
	case mimeExcel:
		return importExcel(name)
	case mimeODS:
		return importODS(name)
	case mimeApacheErr, mimeApacheAcc, mimeNginxAcc, mimeRegexLines:
		return importRegexLines(name, mime)
	}
	return nil, fmt.Errorf("Unknown mimetype for file: %s.", name)
}

func finishImport(raw []byte) (*Imported, error) {
	imp := &Imported{Raw: raw}
	if _, err := imp.FileShape(); err != nil {
		return nil, err
	}
	return imp, nil
}

// ---------------- CSV ----------------

func columnLetter(i int) string {
	s := ""
	i++
	for i > 0 {
		i--
		s = string(rune('A'+i%26)) + s
		i /= 26
	}
	return s
}

type csvRowReader struct {
	r       *csv.Reader
	header  []string
	row     *OrderedMap
	started bool
}

func newCSVRowReader(rd io.Reader, delim rune) *csvRowReader {
	r := csv.NewReader(rd)
	r.Comma = delim
	r.FieldsPerRecord = -1
	return &csvRowReader{r: r, row: NewOrderedMap()}
}

// next returns the next row (reused map) with raw string values; io.EOF at end.
func (c *csvRowReader) next(convertNumbers bool) (*OrderedMap, error) {
	if !c.started {
		c.started = true
		rec, err := c.r.Read()
		if err != nil {
			return nil, err
		}
		for i, h := range rec {
			if h == "" {
				h = columnLetter(i)
			}
			c.header = append(c.header, h)
		}
	}
	rec, err := c.r.Read()
	if err != nil {
		return nil, err
	}
	for i := len(c.header); i < len(rec); i++ {
		c.header = append(c.header, columnLetter(i))
	}
	for i, h := range c.header {
		if i < len(rec) {
			var v interface{} = rec[i]
			if convertNumbers {
				if f, err := strconv.ParseFloat(rec[i], 64); err == nil {
					v = f
				}
			}
			c.row.Set(h, v)
		} else {
			c.row.Set(h, nil)
		}
	}
	return c.row, nil
}

func importCSV(name string, delim rune, convertNumbers bool) (*Imported, error) {
	f, err := openInput(name)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	cr := newCSVRowReader(bufio.NewReader(f), delim)
	w := NewRowsWriter()
	var last *OrderedMap
	for {
		row, err := cr.next(convertNumbers)
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		if err := w.WriteRow(row); err != nil {
			return nil, err
		}
		last = row
	}
	imp := &Imported{Raw: w.Bytes()}
	if last == nil {
		imp.WriterShape = &Shape{Kind: KindArray, Array: unknownShape}
	} else {
		obj := map[string]*Shape{}
		for i, k := range last.Keys {
			obj[k] = GetShape(last.Values[i])
		}
		imp.WriterShape = &Shape{Kind: KindArray, Array: &Shape{Kind: KindObject, Object: obj}}
	}
	return imp, nil
}

func importCSVFast(db *DB, in *inputFile, idx int, convertNumbers bool) error {
	delim := ','
	if in.mime == mimeTSV {
		delim = '\t'
	}
	f, err := openInput(in.name)
	if err != nil {
		return err
	}
	defer f.Close()
	cr := newCSVRowReader(bufio.NewReader(f), delim)
	table := "t_" + strconv.Itoa(idx)
	var cols []string
	var st *Stmt
	typ := "TEXT"
	if convertNumbers {
		typ = "NUMERIC"
	}
	began := false
	for {
		row, err := cr.next(false)
		if err == io.EOF {
			break
		}
		if err != nil {
			if st != nil {
				st.Finalize()
			}
			return err
		}
		if cols == nil {
			cols = append([]string{}, row.Keys...)
			var defs []string
			for _, c := range cols {
				defs = append(defs, `"`+c+`" `+typ)
			}
			if err := db.Exec(`CREATE TABLE "` + table + `"(` + strings.Join(defs, ", ") + `)`); err != nil {
				return err
			}
			ph := make([]string, len(cols))
			for i := range ph {
				ph[i] = "?"
			}
			if err := db.Exec("BEGIN"); err != nil {
				return err
			}
			began = true
			st, err = db.Prepare(`INSERT INTO "` + table + `" VALUES (` + strings.Join(ph, ", ") + `)`)
			if err != nil {
				db.Exec("ROLLBACK")
				return err
			}
		}
		for i, c := range cols {
			v, _ := row.Get(c)
			if err := st.Bind(i+1, v); err != nil {
				st.Finalize()
				return err
			}
		}
		if _, err := st.Step(); err != nil {
			st.Finalize()
			return err
		}
		st.Reset()
	}
	if st != nil {
		st.Finalize()
	}
	if began {
		return db.Exec("COMMIT")
	}
	return nil
}

// ---------------- JSON ----------------

func importJSON(name string) (*Imported, error) {
	raw, err := readInput(name)
	if err != nil {
		return nil, err
	}
	return finishImport(raw)
}

func importJSONL(name string) (*Imported, error) {
	raw, err := readInput(name)
	if err != nil {
		return nil, err
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	w := NewRowsWriter()
	for {
		var v interface{}
		err := dec.Decode(&v)
		if err == io.EOF {
			break
		}
		if err != nil {
			if errors.Is(err, io.ErrUnexpectedEOF) {
				return nil, errors.New("expected comma after object value")
			}
			return nil, err
		}
		if err := w.WriteValue(v); err != nil {
			return nil, err
		}
	}
	return finishImport(w.Bytes())
}

// ---------------- YAML ----------------

func importYAML(name string) (*Imported, error) {
	raw, err := readInput(name)
	if err != nil {
		return nil, err
	}
	dec := yaml.NewDecoder(bytes.NewReader(raw))
	var docs []interface{}
	for {
		var v interface{}
		err := dec.Decode(&v)
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		docs = append(docs, v)
	}
	if len(docs) == 0 {
		return nil, io.EOF
	}
	if len(docs) == 1 {
		var buf bytes.Buffer
		enc := json.NewEncoder(&buf)
		if err := enc.Encode(docs[0]); err != nil {
			return nil, err
		}
		return finishImport(buf.Bytes())
	}
	w := NewRowsWriter()
	for _, d := range docs {
		if err := w.WriteValue(d); err != nil {
			return nil, err
		}
	}
	return finishImport(w.Bytes())
}

// ---------------- text ----------------

func importText(name string) (*Imported, error) {
	raw, err := readInput(name)
	if err != nil {
		return nil, err
	}
	var b strings.Builder
	b.WriteByte('"')
	for _, c := range string(raw) {
		switch c {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		default:
			b.WriteRune(c)
		}
	}
	b.WriteByte('"')
	return finishImport([]byte(b.String()))
}
