package main

import (
	"bufio"
	"bytes"
	"fmt"
	"unicode/utf16"
	"unicode/utf8"
)

type logfmtError struct {
	pos, line int
	msg       string
}

func (e *logfmtError) Error() string {
	return fmt.Sprintf("logfmt syntax error at pos %d on line %d: %s", e.pos, e.line, e.msg)
}

type logfmtDecoder struct {
	line    []byte
	pos     int
	lineNum int
	key     []byte
	value   []byte
	err     error
}

func (dec *logfmtDecoder) unexpectedByte(c byte) {
	dec.err = &logfmtError{pos: dec.pos + 1, line: dec.lineNum, msg: fmt.Sprintf("unexpected %q", c)}
}

func (dec *logfmtDecoder) syntaxError(msg string) {
	dec.err = &logfmtError{pos: dec.pos + 1, line: dec.lineNum, msg: msg}
}

func (dec *logfmtDecoder) scanKeyval() bool {
	dec.key, dec.value = nil, nil
	if dec.err != nil {
		return false
	}
	line := dec.line
	found := false
	for p, c := range line[dec.pos:] {
		if c > ' ' {
			dec.pos += p
			found = true
			break
		}
	}
	if !found {
		dec.pos = len(line)
		return false
	}
	// key
	const invalidKeyError = "invalid key"
	start, multibyte := dec.pos, false
	for p, c := range line[dec.pos:] {
		switch {
		case c == '=':
			dec.pos += p
			if dec.pos > start {
				dec.key = line[start:dec.pos]
				if multibyte && bytes.ContainsRune(dec.key, utf8.RuneError) {
					dec.syntaxError(invalidKeyError)
					return false
				}
			}
			if dec.key == nil {
				dec.unexpectedByte(c)
				return false
			}
			return dec.scanEqual()
		case c == '"':
			dec.pos += p
			dec.unexpectedByte(c)
			return false
		case c <= ' ':
			dec.pos += p
			if dec.pos > start {
				dec.key = line[start:dec.pos]
				if multibyte && bytes.ContainsRune(dec.key, utf8.RuneError) {
					dec.syntaxError(invalidKeyError)
					return false
				}
			}
			return true
		case c >= utf8.RuneSelf:
			multibyte = true
		}
	}
	dec.pos = len(line)
	if dec.pos > start {
		dec.key = line[start:dec.pos]
		if multibyte && bytes.ContainsRune(dec.key, utf8.RuneError) {
			dec.syntaxError(invalidKeyError)
			return false
		}
	}
	return true
}

func (dec *logfmtDecoder) scanEqual() bool {
	line := dec.line
	dec.pos++
	if dec.pos >= len(line) {
		return true
	}
	switch c := line[dec.pos]; {
	case c <= ' ':
		return true
	case c == '"':
		return dec.scanQValue()
	}
	start := dec.pos
	for p, c := range line[dec.pos:] {
		switch {
		case c == '=' || c == '"':
			dec.pos += p
			dec.unexpectedByte(c)
			return false
		case c <= ' ':
			dec.pos += p
			if dec.pos > start {
				dec.value = line[start:dec.pos]
			}
			return true
		}
	}
	dec.pos = len(line)
	if dec.pos > start {
		dec.value = line[start:dec.pos]
	}
	return true
}

func (dec *logfmtDecoder) scanQValue() bool {
	const (
		untermQuote  = "unterminated quoted value"
		invalidQuote = "invalid quoted value"
	)
	line := dec.line
	hasEsc, esc := false, false
	start := dec.pos
	for p, c := range line[dec.pos+1:] {
		switch {
		case esc:
			esc = false
		case c == '\\':
			hasEsc, esc = true, true
		case c == '"':
			dec.pos += p + 2
			if hasEsc {
				v, ok := unquoteBytes(line[start:dec.pos])
				if !ok {
					dec.syntaxError(invalidQuote)
					return false
				}
				dec.value = v
			} else {
				start++
				end := dec.pos - 1
				if end > start {
					dec.value = line[start:end]
				}
			}
			return true
		}
	}
	dec.pos = len(line)
	dec.syntaxError(untermQuote)
	return false
}

func getu4(s []byte) rune {
	if len(s) < 6 || s[0] != '\\' || s[1] != 'u' {
		return -1
	}
	var r rune
	for _, c := range s[2:6] {
		switch {
		case '0' <= c && c <= '9':
			c = c - '0'
		case 'a' <= c && c <= 'f':
			c = c - 'a' + 10
		case 'A' <= c && c <= 'F':
			c = c - 'A' + 10
		default:
			return -1
		}
		r = r*16 + rune(c)
	}
	return r
}

// unquoteBytes is modeled on encoding/json's unquote.
func unquoteBytes(s []byte) (t []byte, ok bool) {
	if len(s) < 2 || s[0] != '"' || s[len(s)-1] != '"' {
		return
	}
	s = s[1 : len(s)-1]
	r := 0
	for r < len(s) {
		c := s[r]
		if c == '\\' || c == '"' || c < ' ' {
			break
		}
		if c < utf8.RuneSelf {
			r++
			continue
		}
		rr, size := utf8.DecodeRune(s[r:])
		if rr == utf8.RuneError && size == 1 {
			break
		}
		r += size
	}
	if r == len(s) {
		return s, true
	}
	b := make([]byte, len(s)+2*utf8.UTFMax)
	w := copy(b, s[0:r])
	for r < len(s) {
		if w >= len(b)-2*utf8.UTFMax {
			nb := make([]byte, (len(b)+utf8.UTFMax)*2)
			copy(nb, b[0:w])
			b = nb
		}
		switch c := s[r]; {
		case c == '\\':
			r++
			if r >= len(s) {
				return
			}
			switch s[r] {
			default:
				return
			case '"', '\\', '/', '\'':
				b[w] = s[r]
				r++
				w++
			case 'b':
				b[w] = '\b'
				r++
				w++
			case 'f':
				b[w] = '\f'
				r++
				w++
			case 'n':
				b[w] = '\n'
				r++
				w++
			case 'r':
				b[w] = '\r'
				r++
				w++
			case 't':
				b[w] = '\t'
				r++
				w++
			case 'u':
				r--
				rr := getu4(s[r:])
				if rr < 0 {
					return
				}
				r += 6
				if utf16.IsSurrogate(rr) {
					rr1 := getu4(s[r:])
					if dec := utf16.DecodeRune(rr, rr1); dec != utf8.RuneError {
						r += 6
						w += utf8.EncodeRune(b[w:], dec)
						break
					}
					rr = utf8.RuneError
				}
				w += utf8.EncodeRune(b[w:], rr)
			}
		case c == '"', c < ' ':
			return
		case c < utf8.RuneSelf:
			b[w] = c
			r++
			w++
		default:
			rr, size := utf8.DecodeRune(s[r:])
			r += size
			w += utf8.EncodeRune(b[w:], rr)
		}
	}
	return b[0:w], true
}

func importLogfmt(name string) (*Imported, error) {
	f, err := openInput(name)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	w := NewRowsWriter()
	lineNum := 0
	for sc.Scan() {
		lineNum++
		dec := &logfmtDecoder{line: sc.Bytes(), lineNum: lineNum}
		row := NewOrderedMap()
		for dec.scanKeyval() {
			row.Set(string(dec.key), string(dec.value))
		}
		if dec.err != nil {
			return nil, dec.err
		}
		if err := w.WriteRow(row); err != nil {
			return nil, err
		}
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	return finishImport(w.Bytes())
}
