package main

import (
	"crypto/md5"
	"crypto/sha1"
	"crypto/sha256"
	"crypto/sha512"
	"encoding/base32"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"math"
	"net/url"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

// goPanic is raised from inside SQL functions to emulate Go runtime panics
// in the original implementation. It aborts the program with exit code 2.
type goPanic struct{ msg string }

func raisePanic(msg string) {
	panic(goPanic{msg})
}

var (
	errArgInt     = errors.New("argument must be an INTEGER")
	errArgFloat   = errors.New("argument must be an INTEGER or FLOAT")
	errArgString  = errors.New("argument must be BLOB or TEXT")
)

func argString(v sqlValue) (string, error) {
	switch v.Type() {
	case sqlText:
		return v.Text(), nil
	case sqlBlob:
		return string(v.Blob()), nil
	}
	return "", errArgString
}

func argInt(v sqlValue) (int64, error) {
	if v.Type() != sqlInteger {
		return 0, errArgInt
	}
	return v.Int64(), nil
}

func argFloat(v sqlValue) (float64, error) {
	switch v.Type() {
	case sqlInteger:
		return float64(v.Int64()), nil
	case sqlFloat:
		return v.Float(), nil
	}
	return 0, errArgFloat
}

// generic conversions used by go-sqlite3-stdlib style helpers
func toFloat(v interface{}) float64 {
	switch t := v.(type) {
	case int64:
		return float64(t)
	case float64:
		return t
	case string:
		f, err := strconv.ParseFloat(t, 64)
		if err != nil {
			return 0
		}
		return f
	case bool:
		if t {
			return 1
		}
		return 0
	}
	return 0
}

func toInt(v interface{}) int {
	switch t := v.(type) {
	case int64:
		return int(t)
	case float64:
		return int(t)
	case string:
		i, err := strconv.Atoi(t)
		if err != nil {
			return 0
		}
		return i
	}
	return 0
}

func toStr(v interface{}) string {
	switch t := v.(type) {
	case string:
		return t
	case []byte:
		if len(t) == 0 {
			return "null"
		}
		return string(t)
	case int64:
		return strconv.FormatInt(t, 10)
	case float64:
		return fmt.Sprintf("%v", t)
	case nil:
		return "null"
	}
	return fmt.Sprintf("%v", v)
}

func gen(args []sqlValue, i int) interface{} {
	if i >= len(args) {
		return nil
	}
	return args[i].Generic()
}

func mathFunc1(f func(float64) float64) scalarFunc {
	return func(args []sqlValue) (interface{}, error) {
		return f(toFloat(gen(args, 0))), nil
	}
}

func mathFunc2(f func(float64, float64) float64) scalarFunc {
	return func(args []sqlValue) (interface{}, error) {
		return f(toFloat(gen(args, 0)), toFloat(gen(args, 1))), nil
	}
}

func padImpl(args []sqlValue, left bool) (interface{}, error) {
	if len(args) < 2 {
		return nil, errors.New("function requires at least 2 arguments")
	}
	str := toStr(args[0].Generic())
	n64, err := argInt(args[1])
	if err != nil {
		return nil, err
	}
	length := int(n64)
	if len(str) >= length {
		if length < 0 {
			raisePanic(fmt.Sprintf("runtime error: slice bounds out of range [:%d]", length))
		}
		return str[:length], nil
	}
	p := " "
	if len(args) > 2 {
		p = toStr(args[2].Generic())
	}
	need := length - len(str)
	pr := []rune(p)
	if len(pr) == 0 {
		raisePanic("runtime error: integer divide by zero")
	}
	reps := need / len(pr)
	rem := need % len(pr)
	padding := strings.Repeat(p, reps) + string(pr[:rem])
	if left {
		res := padding + str
		if len(res) > length {
			res = res[:length]
		}
		return res, nil
	}
	return str + padding, nil
}

func repeatImpl(args []sqlValue) (interface{}, error) {
	s := toStr(args[0].Generic())
	n, err := argInt(args[1])
	if err != nil {
		return nil, err
	}
	if n <= 0 {
		return "", nil
	}
	return strings.Repeat(s, int(n)), nil
}

func splitIndex(parts []string, idx int) string {
	if idx < 0 {
		i := len(parts) + idx
		if i < 0 {
			raisePanic(fmt.Sprintf("runtime error: index out of range [%d]", i))
		}
		return parts[i]
	}
	if idx >= len(parts) {
		return ""
	}
	return parts[idx]
}

var regexCache = map[string]*regexp.Regexp{}
var regexErrCache = map[string]bool{}

func compileRegex(p string) (*regexp.Regexp, bool) {
	if re, ok := regexCache[p]; ok {
		return re, true
	}
	if regexErrCache[p] {
		return nil, false
	}
	re, err := regexp.Compile(p)
	if err != nil {
		regexErrCache[p] = true
		return nil, false
	}
	regexCache[p] = re
	return re, true
}

// ---- aggregates ----

type collectAgg struct {
	vals []interface{}
	kind string
	p    float64
	pSet bool
}

func (a *collectAgg) Step(args []sqlValue) error {
	if len(args) == 0 {
		return nil
	}
	v := args[0].Generic()
	a.vals = append(a.vals, v)
	if len(args) > 1 {
		a.p = toFloat(args[1].Generic())
	}
	return nil
}

func sortFloats(vals []interface{}) []float64 {
	fs := make([]float64, len(vals))
	for i, v := range vals {
		fs[i] = toFloat(v)
	}
	sort.Float64s(fs)
	return fs
}

func variance(x []float64) float64 {
	if len(x) < 2 {
		return 0
	}
	var sum float64
	for _, v := range x {
		sum += v
	}
	mean := sum / float64(len(x))
	var ss, comp float64
	for _, v := range x {
		d := v - mean
		ss += d * d
		comp += d
	}
	return (ss - comp*comp/float64(len(x))) / float64(len(x)-1)
}

func empiricalQuantile(p float64, x []float64) float64 {
	var cumsum float64
	fidx := p * float64(len(x))
	for i := range x {
		cumsum++
		if cumsum >= fidx {
			return x[i]
		}
	}
	raisePanic("impossible")
	return 0
}

func linInterpQuantile(p float64, x []float64) float64 {
	var cumsum float64
	fidx := p * float64(len(x))
	for i := range x {
		cumsum++
		if cumsum >= fidx {
			if i == 0 {
				return x[0]
			}
			t := cumsum - fidx
			return t*x[i-1] + (1-t)*x[i]
		}
	}
	raisePanic("impossible")
	return 0
}

func genericLess(a, b interface{}) bool {
	rank := func(v interface{}) int {
		switch t := v.(type) {
		case int64, float64:
			return 1
		case string:
			return 2
		case []byte:
			if t == nil {
				return 4
			}
			return 3
		}
		return 5
	}
	ra, rb := rank(a), rank(b)
	if ra != rb {
		return ra < rb
	}
	switch ra {
	case 1:
		return toFloat(a) < toFloat(b)
	case 2:
		return a.(string) < b.(string)
	case 3:
		return string(a.([]byte)) < string(b.([]byte))
	}
	return false
}

func (a *collectAgg) Done() (interface{}, error) {
	switch a.kind {
	case "stddev":
		return variance(sortFloatsNoSort(a.vals)), nil
	case "median":
		if len(a.vals) == 0 {
			return nil, nil
		}
		vals := append([]interface{}{}, a.vals...)
		sort.SliceStable(vals, func(i, j int) bool { return genericLess(vals[i], vals[j]) })
		return vals[len(vals)/2], nil
	case "mode":
		if len(a.vals) == 0 {
			return nil, nil
		}
		counts := map[interface{}]int{}
		keyOf := func(v interface{}) interface{} {
			if b, ok := v.([]byte); ok {
				raisePanic("runtime error: hash of unhashable type []uint8")
				return string(b)
			}
			return v
		}
		for _, v := range a.vals {
			counts[keyOf(v)]++
		}
		var best interface{}
		bestN := -1
		for _, v := range a.vals {
			if c := counts[keyOf(v)]; c > bestN {
				bestN = c
				best = v
			}
		}
		return best, nil
	case "perc", "perc_cont":
		p := a.p
		if !a.pSet {
			p = a.p
		}
		if p < 0 || p > 100 || math.IsNaN(p) {
			raisePanic("stat: percentile out of bounds")
		}
		if p == 0 || len(a.vals) == 0 {
			return float64(0), nil
		}
		x := sortFloats(a.vals)
		if a.kind == "perc" {
			return empiricalQuantile(p/100, x), nil
		}
		return linInterpQuantile(p/100, x), nil
	}
	return nil, nil
}

func sortFloatsNoSort(vals []interface{}) []float64 {
	fs := make([]float64, len(vals))
	for i, v := range vals {
		fs[i] = toFloat(v)
	}
	return fs
}

// ---- registration ----

func registerFunctions(d *DB) {
	det := true
	// math
	m1 := map[string]func(float64) float64{
		"acos": math.Acos, "acosh": math.Acosh, "asin": math.Asin, "asinh": math.Asinh,
		"atan": math.Atan, "atanh": math.Atanh, "ceil": math.Ceil, "ceiling": math.Ceil,
		"cos": math.Cos, "cosh": math.Cosh, "exp": math.Exp, "floor": math.Floor,
		"ln": math.Log, "log": math.Log, "log10": math.Log10, "log2": math.Log2,
		"sin": math.Sin, "sinh": math.Sinh, "sqrt": math.Sqrt, "tan": math.Tan,
		"tanh": math.Tanh, "trunc": math.Trunc, "truncate": math.Trunc,
		"degrees": func(x float64) float64 { return x * 180 / math.Pi },
		"radians": func(x float64) float64 { return x * math.Pi / 180 },
	}
	for name, f := range m1 {
		d.CreateFunction(name, 1, det, mathFunc1(f))
	}
	d.CreateFunction("log", 2, det, func(args []sqlValue) (interface{}, error) {
		return nil, errors.New("wrong number of arguments to function log()")
	})
	d.CreateFunction("pi", 0, det, func(args []sqlValue) (interface{}, error) { return math.Pi, nil })
	d.CreateFunction("pow", 2, det, mathFunc2(math.Pow))
	d.CreateFunction("power", 2, det, mathFunc2(math.Pow))
	d.CreateFunction("mod", 2, det, mathFunc2(math.Mod))

	// strings
	idx := func(args []sqlValue) (interface{}, error) {
		return int64(strings.Index(toStr(args[0].Generic()), toStr(args[1].Generic()))), nil
	}
	d.CreateFunction("charindex", 2, det, idx)
	d.CreateFunction("strpos", 2, det, idx)
	d.CreateFunction("len", 1, det, func(args []sqlValue) (interface{}, error) {
		return int64(len(toStr(args[0].Generic()))), nil
	})
	d.CreateFunction("lpad", -1, det, func(args []sqlValue) (interface{}, error) { return padImpl(args, true) })
	d.CreateFunction("rpad", -1, det, func(args []sqlValue) (interface{}, error) { return padImpl(args, false) })
	d.CreateFunction("repeat", 2, det, repeatImpl)
	d.CreateFunction("replicate", 2, det, repeatImpl)
	d.CreateFunction("reverse", 1, det, func(args []sqlValue) (interface{}, error) {
		r := []rune(toStr(args[0].Generic()))
		for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
			r[i], r[j] = r[j], r[i]
		}
		return string(r), nil
	})
	d.CreateFunction("split_part", 3, det, func(args []sqlValue) (interface{}, error) {
		parts := strings.Split(toStr(args[0].Generic()), toStr(args[1].Generic()))
		return splitIndex(parts, toInt(args[2].Generic())), nil
	})
	d.CreateFunction("regexp", 2, det, func(args []sqlValue) (interface{}, error) {
		p, err := argString(args[0])
		if err != nil {
			return nil, err
		}
		s, err := argString(args[1])
		if err != nil {
			return nil, err
		}
		re, ok := compileRegex(p)
		if !ok {
			return false, nil
		}
		return re.MatchString(s), nil
	})
	d.CreateFunction("regexp_count", 2, det, func(args []sqlValue) (interface{}, error) {
		s := toStr(args[0].Generic())
		re, ok := compileRegex(toStr(args[1].Generic()))
		if !ok {
			return int64(0), nil
		}
		return int64(len(re.FindAllStringIndex(s, -1))), nil
	})
	d.CreateFunction("regexp_split_part", 3, det, func(args []sqlValue) (interface{}, error) {
		s := toStr(args[0].Generic())
		re, ok := compileRegex(toStr(args[1].Generic()))
		if !ok {
			return "", nil
		}
		i := toInt(args[2].Generic())
		if i >= 0 {
			parts := re.Split(s, i+1)
			if i >= len(parts) {
				return "", nil
			}
			return parts[i], nil
		}
		parts := re.Split(s, -1)
		return splitIndex(parts, i), nil
	})

	// url
	urlFn := func(f func(u *url.URL) string) scalarFunc {
		return func(args []sqlValue) (interface{}, error) {
			s, err := argString(args[0])
			if err != nil {
				return nil, err
			}
			u, err := url.Parse(s)
			if err != nil {
				return "", nil
			}
			return f(u), nil
		}
	}
	d.CreateFunction("url_host", 1, det, urlFn(func(u *url.URL) string { return u.Host }))
	d.CreateFunction("url_path", 1, det, urlFn(func(u *url.URL) string { return u.Path }))
	d.CreateFunction("url_port", 1, det, urlFn(func(u *url.URL) string { return u.Port() }))
	d.CreateFunction("url_scheme", 1, det, urlFn(func(u *url.URL) string { return u.Scheme }))
	d.CreateFunction("url_fragment", 1, det, urlFn(func(u *url.URL) string { return u.Fragment }))
	d.CreateFunction("url_param", 2, det, func(args []sqlValue) (interface{}, error) {
		s, err := argString(args[0])
		if err != nil {
			return nil, err
		}
		name, err := argString(args[1])
		if err != nil {
			return nil, err
		}
		u, err := url.Parse(s)
		if err != nil {
			return "", nil
		}
		return u.Query().Get(name), nil
	})

	// hashes & encodings
	hashFn := func(f func([]byte) []byte) scalarFunc {
		return func(args []sqlValue) (interface{}, error) {
			return hex.EncodeToString(f([]byte(toStr(args[0].Generic())))), nil
		}
	}
	d.CreateFunction("md5", 1, det, hashFn(func(b []byte) []byte { h := md5.Sum(b); return h[:] }))
	d.CreateFunction("sha1", 1, det, hashFn(func(b []byte) []byte { h := sha1.Sum(b); return h[:] }))
	d.CreateFunction("sha256", 1, det, hashFn(func(b []byte) []byte { h := sha256.Sum256(b); return h[:] }))
	d.CreateFunction("sha512", 1, det, hashFn(func(b []byte) []byte { h := sha512.Sum512(b); return h[:] }))
	d.CreateFunction("sha3_256", 1, det, hashFn(func(b []byte) []byte { return sha3Sum(b, 32) }))
	d.CreateFunction("sha3_512", 1, det, hashFn(func(b []byte) []byte { return sha3Sum(b, 64) }))
	d.CreateFunction("blake2b_256", 1, det, hashFn(func(b []byte) []byte { return blake2bSum(b, 32) }))
	d.CreateFunction("blake2b_512", 1, det, hashFn(func(b []byte) []byte { return blake2bSum(b, 64) }))
	d.CreateFunction("base64", 1, det, func(args []sqlValue) (interface{}, error) {
		return base64.StdEncoding.EncodeToString([]byte(toStr(args[0].Generic()))), nil
	})
	d.CreateFunction("base32", 1, det, func(args []sqlValue) (interface{}, error) {
		return base32.StdEncoding.EncodeToString([]byte(toStr(args[0].Generic()))), nil
	})
	d.CreateFunction("from_base64", 1, det, func(args []sqlValue) (interface{}, error) {
		b, err := base64.StdEncoding.DecodeString(toStr(args[0].Generic()))
		if err != nil {
			return "", nil
		}
		return string(b), nil
	})
	d.CreateFunction("from_base32", 1, det, func(args []sqlValue) (interface{}, error) {
		b, err := base32.StdEncoding.DecodeString(toStr(args[0].Generic()))
		if err != nil {
			return "", nil
		}
		return string(b), nil
	})

	// dates
	dateInt := func(f func(t dateResult) int64) scalarFunc {
		return func(args []sqlValue) (interface{}, error) {
			t, ok := parseDateArg(args[0].Generic())
			if !ok {
				return int64(-1), nil
			}
			return f(t), nil
		}
	}
	d.CreateFunction("date_year", 1, det, dateInt(func(t dateResult) int64 { return int64(t.t.Year()) }))
	d.CreateFunction("date_month", 1, det, dateInt(func(t dateResult) int64 { return int64(t.t.Month()) }))
	d.CreateFunction("date_day", 1, det, dateInt(func(t dateResult) int64 { return int64(t.t.Day()) }))
	d.CreateFunction("date_yearday", 1, det, dateInt(func(t dateResult) int64 { return int64(t.t.YearDay()) }))
	d.CreateFunction("date_hour", 1, det, dateInt(func(t dateResult) int64 { return int64(t.t.Hour()) }))
	d.CreateFunction("date_minute", 1, det, dateInt(func(t dateResult) int64 { return int64(t.t.Minute()) }))
	d.CreateFunction("date_second", 1, det, dateInt(func(t dateResult) int64 { return int64(t.t.Second()) }))
	d.CreateFunction("date_unix", 1, det, dateInt(func(t dateResult) int64 { return t.t.Unix() }))
	d.CreateFunction("date_rfc3339", 1, det, func(args []sqlValue) (interface{}, error) {
		t, ok := parseDateArg(args[0].Generic())
		if !ok {
			return "", nil
		}
		return t.t.Format("2006-01-02T15:04:05Z07:00"), nil
	})

	// aggregates
	aggs := map[string]func() aggImpl{
		"stddev":     func() aggImpl { return &collectAgg{kind: "stddev"} },
		"stddev_pop": func() aggImpl { return &collectAgg{kind: "stddev"} },
		"stdev":      func() aggImpl { return &collectAgg{kind: "stddev"} },
		"median":     func() aggImpl { return &collectAgg{kind: "median"} },
		"mode":       func() aggImpl { return &collectAgg{kind: "mode"} },
	}
	for name, f := range aggs {
		d.CreateAggregate(name, 1, aggFactory(f))
	}
	percs := []struct {
		suffix string
		p      float64
	}{{"", 0}, {"_25", 25}, {"_50", 50}, {"_75", 75}, {"_90", 90}, {"_95", 95}, {"_99", 99}}
	for _, pc := range percs {
		p := pc.p
		for _, base := range []string{"perc", "percentile"} {
			d.CreateAggregate(base+pc.suffix, -1, func() aggImpl { return &collectAgg{kind: "perc", p: p} })
			d.CreateAggregate(base+"_cont"+pc.suffix, -1, func() aggImpl { return &collectAgg{kind: "perc_cont", p: p} })
		}
	}

	// SQLite 3.39 compatibility shims
	d.CreateFunction("sqlite_version", 0, det, func(args []sqlValue) (interface{}, error) { return "3.39.2", nil })
	d.CreateFunction("sqlite_source_id", 0, det, func(args []sqlValue) (interface{}, error) {
		return "2022-07-21 15:24:47 698edb77537b67c41adc68f9b892db56bcf9a55e00371a61420f3ddd668e6603", nil
	})
	registerCompatFunctions(d)
}
EOF
echo ok"}

