package main

import (
	"crypto/md5"
	"crypto/sha1"
	"crypto/sha256"
	"crypto/sha512"
	"encoding/base32"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"math"
	"net/url"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

// goPanic is raised from inside SQL functions to emulate Go runtime panics
// in the original implementation. It aborts the program with exit code 2.
type goPanic struct{ msg string }

func raisePanic(msg string) {
	panic(goPanic{msg})
}

var (
	errArgInt     = errors.New("argument must be an INTEGER")
	errArgFloat   = errors.New("argument must be an INTEGER or FLOAT")
	errArgString  = errors.New("argument must be BLOB or TEXT")
)

func argString(v sqlValue) (string, error) {
	switch v.Type() {
	case sqlText:
		return v.Text(), nil
	case sqlBlob:
		return string(v.Blob()), nil
	}
	return "", errArgString
}

func argInt(v sqlValue) (int64, error) {
	if v.Type() != sqlInteger {
		return 0, errArgInt
	}
	return v.Int64(), nil
}

func argFloat(v sqlValue) (float64, error) {
	switch v.Type() {
	case sqlInteger:
		return float64(v.Int64()), nil
	case sqlFloat:
		return v.Float(), nil
	}
	return 0, errArgFloat
}

// generic conversions used by go-sqlite3-stdlib style helpers
func toFloat(v interface{}) float64 {
	switch t := v.(type) {
	case int64:
		return float64(t)
	case float64:
		return t
	case string:
		f, err := strconv.ParseFloat(t, 64)
		if err != nil {
			return 0
		}
		return f
	case bool:
		if t {
			return 1
		}
		return 0
	}
	return 0
}

func toInt(v interface{}) int {
	switch t := v.(type) {
	case int64:
		return int(t)
	case float64:
		return int(t)
	case string:
		i, err := strconv.Atoi(t)
		if err != nil {
			return 0
		}
		return i
	}
	return 0
}

func toStr(v interface{}) string {
	switch t := v.(type) {
	case string:
		return t
	case []byte:
		if len(t) == 0 {
			return "null"
		}
		return string(t)
	case int64:
		return strconv.FormatInt(t, 10)
	case float64:
		return fmt.Sprintf("%v", t)
	case nil:
		return "null"
	}
	return fmt.Sprintf("%v", v)
}

func gen(args []sqlValue, i int) interface{} {
	if i >= len(args) {
		return nil
	}
	return args[i].Generic()
}

func mathFunc1(f func(float64) float64) scalarFunc {
	return func(args []sqlValue) (interface{}, error) {
		return f(toFloat(gen(args, 0))), nil
	}
}

func mathFunc2(f func(float64, float64) float64) scalarFunc {
	return func(args []sqlValue) (interface{}, error) {
		return f(toFloat(gen(args, 0)), toFloat(gen(args, 1))), nil
	}
}

func padImpl(args []sqlValue, left bool) (interface{}, error) {
	if len(args) < 2 {
		return nil, errors.New("function requires at least 2 arguments")
	}
	str := toStr(args[0].Generic())
	n64, err := argInt(args[1])
	if err != nil {
		return nil, err
	}
	length := int(n64)
	if len(str) >= length {
		if length < 0 {
			raisePanic(fmt.Sprintf("runtime error: slice bounds out of range [:%d]", length))
		}
		return str[:length], nil
	}
	p := " "
	if len(args) > 2 {
		p = toStr(args[2].Generic())
	}
	need := length - len(str)
	pr := []rune(p)
	if len(pr) == 0 {
		raisePanic("runtime error: integer divide by zero")
	}
	reps := need / len(pr)
	rem := need % len(pr)
	padding := strings.Repeat(p, reps) + string(pr[:rem])
	if left {
		res := padding + str
		if len(res) > length {
			res = res[:length]
		}
		return res, nil
	}
	return str + padding, nil
}

func repeatImpl(args []sqlValue) (interface{}, error) {
	s := toStr(args[0].Generic())
	n, err := argInt(args[1])
	if err != nil {
		return nil, err
	}
	if n <= 0 {
		return "", nil
	}
	return strings.Repeat(s, int(n)), nil
}

func splitIndex(parts []string, idx int) string {
	if idx < 0 {
		i := len(parts) + idx
		if i < 0 {
			raisePanic(fmt.Sprintf("runtime error: index out of range [%d]", i))
		}
		return parts[i]
	}
	if idx >= len(parts) {
		return ""
	}
	return parts[idx]
}

var regexCache = map[string]*regexp.Regexp{}
var regexErrCache = map[string]bool{}

func compileRegex(p string) (*regexp.Regexp, bool) {
	if re, ok := regexCache[p]; ok {
		return re, true
	}
	if regexErrCache[p] {
		return nil, false
	}
	re, err := regexp.Compile(p)
	if err != nil {
		regexErrCache[p] = true
		return nil, false
	}
	regexCache[p] = re
	return re, true
}

// ---- aggregates ----

type collectAgg struct {
	vals []interface{}
	kind string
	p    float64
	pSet bool
}

func (a *collectAgg) Step(args []sqlValue) error {
	if len(args) == 0 {
		return nil
	}
	v := args[0].Generic()
	a.vals = append(a.vals, v)
	if len(args) > 1 {
		a.p = toFloat(args[1].Generic())
	}
	return nil
}

func sortFloats(vals []interface{}) []float64 {
	fs := make([]float64, len(vals))
	for i, v := range vals {
		fs[i] = toFloat(v)
	}
	sort.Float64s(fs)
	return fs
}

func variance(x []float64) float64 {
	if len(x) < 2 {
		return 0
	}
	var sum float64
	for _, v := range x {
		sum += v
	}
	mean := sum / float64(len(x))
	var ss, comp float64
	for _, v := range x {
		d := v - mean
		ss += d * d
		comp += d
	}
	return (ss - comp*comp/float64(len(x))) / float64(len(x)-1)
}

func empiricalQuantile(p float64, x []float64) float64 {
	var cumsum float64
	fidx := p * float64(len(x))
	for i := range x {
		cumsum++
		if cumsum >= fidx {
			return x[i]
		}
	}
	raisePanic("impossible")
	return 0
}

func linInterpQuantile(p float64, x []float64) float64 {
	var cumsum float64
	fidx := p * float64(len(x))
	for i := range x {
		cumsum++
		if cumsum >= fidx {
			if i == 0 {
				return x[0]
			}
			t := cumsum - fidx
			return t*x[i-1] + (1-t)*x[i]
		}
	}
	raisePanic("impossible")
	return 0
}

func genericLess(a, b interface{}) bool {
	rank := func(v interface{}) int {
		switch t := v.(type) {
		case int64, float64:
			return 1
		case string:
			return 2
		case []byte:
			if t == nil {
				return 4
			}
			return 3
		}
		return 5
	}
	ra, rb := rank(a), rank(b)
	if ra != rb {
		return ra < rb
	}
	switch ra {
	case 1:
		return toFloat(a) < toFloat(b)
	case 2:
		return a.(string) < b.(string)
	case 3:
		return string(a.([]byte)) < string(b.([]byte))
	}
	return false
}

func (a *collectAgg) Done() (interface{}, error) {
	switch a.kind {
	case "stddev":
		return variance(sortFloatsNoSort(a.vals)), nil
	case "median":
		if len(a.vals) == 0 {
			return nil, nil
		}
		vals := append([]interface{}{}, a.vals...)
		sort.SliceStable(vals, func(i, j int) bool { return genericLess(vals[i], vals[j]) })
		return vals[len(vals)/2], nil
	case "mode":
		if len(a.vals) == 0 {
			return nil, nil
		}
		counts := map[interface{}]int{}
		keyOf := func(v interface{}) interface{} {
			if b, ok := v.([]byte); ok {
				raisePanic("runtime error: hash of unhashable type []uint8")
				return string(b)
			}
			return v
		}
		for _, v := range a.vals {
			counts[keyOf(v)]++
		}
		var best interface{}
		bestN := -1
		for _, v := range a.vals {
			if c := counts[keyOf(v)]; c > bestN {
				bestN = c
				best = v
			}
		}
		return best, nil
	case "perc", "perc_cont":
		p := a.p
		if !a.pSet {
			p = a.p
		}
		if p < 0 || p > 100 || math.IsNaN(p) {
			raisePanic("stat: percentile out of bounds")
		}
		if p == 0 || len(a.vals) == 0 {
			return float64(0), nil
		}
		x := sortFloats(a.vals)
		if a.kind == "perc" {
			return empiricalQuantile(p/100, x), nil
		}
		return linInterpQuantile(p/100, x), nil
	}
	return nil, nil
}

func sortFloatsNoSort(vals []interface{}) []float64 {
	fs := make([]float64, len(vals))
	for i, v := range vals {
		fs[i] = toFloat(v)
	}
	return fs
}

// ---- registration ----

func registerFunctions(d *DB) {
