package main

import (
	"encoding/binary"
	"errors"
	"math"
)

// Minimal Thrift compact protocol decoder producing generic structures.

type tStruct map[int16]interface{}

type thriftReader struct {
	b   []byte
	pos int
}

var errThriftEOF = errors.New("thrift: unexpected end of data")

func (r *thriftReader) byte() (byte, error) {
	if r.pos >= len(r.b) {
		return 0, errThriftEOF
	}
	c := r.b[r.pos]
	r.pos++
	return c, nil
}

func (r *thriftReader) varint() (uint64, error) {
	var x uint64
	var s uint
	for i := 0; i < 10; i++ {
		c, err := r.byte()
		if err != nil {
			return 0, err
		}
		x |= uint64(c&0x7f) << s
		if c&0x80 == 0 {
			return x, nil
		}
		s += 7
	}
	return 0, errors.New("thrift: varint overflow")
}

func (r *thriftReader) zigzag() (int64, error) {
	v, err := r.varint()
	if err != nil {
		return 0, err
	}
	return int64(v>>1) ^ -int64(v&1), nil
}

func (r *thriftReader) readValue(t byte) (interface{}, error) {
	switch t {
	case 1:
		return true, nil
	case 2:
		return false, nil
	case 3:
		c, err := r.byte()
		return int64(int8(c)), err
	case 4, 5, 6:
		return r.zigzag()
	case 7:
		if r.pos+8 > len(r.b) {
			return nil, errThriftEOF
		}
		v := math.Float64frombits(binary.LittleEndian.Uint64(r.b[r.pos:]))
		r.pos += 8
		return v, nil
	case 8:
		n, err := r.varint()
		if err != nil {
			return nil, err
		}
		if r.pos+int(n) > len(r.b) || int(n) < 0 {
			return nil, errThriftEOF
		}
		v := r.b[r.pos : r.pos+int(n)]
		r.pos += int(n)
		return v, nil
	case 9, 10:
		h, err := r.byte()
		if err != nil {
			return nil, err
		}
		n := int(h >> 4)
		et := h & 0x0f
		if n == 15 {
			m, err := r.varint()
			if err != nil {
				return nil, err
			}
			n = int(m)
		}
		list := make([]interface{}, 0, n)
		for i := 0; i < n; i++ {
			var v interface{}
			if et == 1 || et == 2 {
				c, err := r.byte()
				if err != nil {
					return nil, err
				}
				v = c == 1
			} else {
				v, err = r.readValue(et)
				if err != nil {
					return nil, err
				}
			}
			list = append(list, v)
		}
		return list, nil
	case 11:
		n, err := r.varint()
		if err != nil {
			return nil, err
		}
		if n == 0 {
			return map[interface{}]interface{}{}, nil
		}
		kt, err := r.byte()
		if err != nil {
			return nil, err
		}
		m := map[interface{}]interface{}{}
		for i := 0; i < int(n); i++ {
			k, err := r.readValue(kt >> 4)
			if err != nil {
				return nil, err
			}
			v, err := r.readValue(kt & 0xf)
			if err != nil {
				return nil, err
			}
			if kb, ok := k.([]byte); ok {
				k = string(kb)
			}
			m[k] = v
		}
		return m, nil
	case 12:
		return r.readStruct()
	}
	return nil, errors.New("thrift: unknown type")
}

func (r *thriftReader) readStruct() (tStruct, error) {
	s := tStruct{}
	var last int16
	for {
		h, err := r.byte()
		if err != nil {
			return nil, err
		}
		if h == 0 {
			return s, nil
		}
		t := h & 0x0f
		delta := int16(h >> 4)
		var fid int16
		if delta == 0 {
			v, err := r.zigzag()
			if err != nil {
				return nil, err
			}
			fid = int16(v)
		} else {
			fid = last + delta
		}
		last = fid
		v, err := r.readValue(t)
		if err != nil {
			return nil, err
		}
		s[fid] = v
	}
}

func (s tStruct) int(f int16, def int64) int64 {
	if v, ok := s[f].(int64); ok {
		return v
	}
	return def
}

func (s tStruct) has(f int16) bool {
	_, ok := s[f]
	return ok
}

func (s tStruct) str(f int16) string {
	if v, ok := s[f].([]byte); ok {
		return string(v)
	}
	return ""
}

func (s tStruct) bytes(f int16) []byte {
	if v, ok := s[f].([]byte); ok {
		return v
	}
	return nil
}

func (s tStruct) bool(f int16, def bool) bool {
	if v, ok := s[f].(bool); ok {
		return v
	}
	return def
}

func (s tStruct) strct(f int16) tStruct {
	if v, ok := s[f].(tStruct); ok {
		return v
	}
	return nil
}

func (s tStruct) list(f int16) []interface{} {
	if v, ok := s[f].([]interface{}); ok {
		return v
	}
	return nil
}
