package main

import (
	"encoding/binary"
	"errors"
)

var errSnappyCorrupt = errors.New("snappy: corrupt input")

func snappyDecode(src []byte) ([]byte, error) {
	dLen, n := binary.Uvarint(src)
	if n <= 0 {
		return nil, errSnappyCorrupt
	}
	src = src[n:]
	dst := make([]byte, 0, dLen)
	for len(src) > 0 {
		tag := src[0]
		switch tag & 3 {
		case 0:
			l := int(tag >> 2)
			src = src[1:]
			switch {
			case l < 60:
			case l == 60:
				if len(src) < 1 {
					return nil, errSnappyCorrupt
				}
				l = int(src[0])
				src = src[1:]
			case l == 61:
				if len(src) < 2 {
					return nil, errSnappyCorrupt
				}
				l = int(src[0]) | int(src[1])<<8
				src = src[2:]
			case l == 62:
				if len(src) < 3 {
					return nil, errSnappyCorrupt
				}
				l = int(src[0]) | int(src[1])<<8 | int(src[2])<<16
				src = src[3:]
			case l == 63:
				if len(src) < 4 {
					return nil, errSnappyCorrupt
				}
				l = int(src[0]) | int(src[1])<<8 | int(src[2])<<16 | int(src[3])<<24
				src = src[4:]
			}
			l++
			if l > len(src) {
				return nil, errSnappyCorrupt
			}
			dst = append(dst, src[:l]...)
			src = src[l:]
		case 1:
			if len(src) < 2 {
				return nil, errSnappyCorrupt
			}
			length := 4 + int(tag>>2)&7
			offset := int(tag&0xe0)<<3 | int(src[1])
			src = src[2:]
			if err := snappyCopy(&dst, offset, length); err != nil {
				return nil, err
			}
		case 2:
			if len(src) < 3 {
				return nil, errSnappyCorrupt
			}
			length := 1 + int(tag>>2)
			offset := int(src[1]) | int(src[2])<<8
			src = src[3:]
			if err := snappyCopy(&dst, offset, length); err != nil {
				return nil, err
			}
		case 3:
			if len(src) < 5 {
				return nil, errSnappyCorrupt
			}
			length := 1 + int(tag>>2)
			offset := int(binary.LittleEndian.Uint32(src[1:5]))
			src = src[5:]
			if err := snappyCopy(&dst, offset, length); err != nil {
				return nil, err
			}
		}
	}
	if uint64(len(dst)) != dLen {
		return nil, errSnappyCorrupt
	}
	return dst, nil
}

func snappyCopy(dst *[]byte, offset, length int) error {
	d := *dst
	if offset <= 0 || offset > len(d) {
		return errSnappyCorrupt
	}
	start := len(d) - offset
	for i := 0; i < length; i++ {
		d = append(d, d[start+i])
	}
	*dst = d
	return nil
}
