cd /workspace && cat > parquet.go <<'EOF'
package main

import (
	"bytes"
	"compress/gzip"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"math"
	"os"
	"strconv"
	"strings"
)

type pqNode struct {
	name       string
	exName     string
	repetition int64 // 0 required, 1 optional, 2 repeated
	physType   int64
	typeLen    int64
	convType   int64
	children   []*pqNode
	leafIdx    int
	maxDef     int
	maxRep     int
	defLevel   int // def level at which this node is present
	repLevel   int
}

type pqTriple struct {
	rep, def int
	val      interface{}
}

func isPqLetter(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isPqDigit(c byte) bool {
	return c >= '0' && c <= '9'
}

func pqVariableName(str string) string {
	if len(str) == 0 {
		return str
	}
	var b strings.Builder
	for i := 0; i < len(str); i++ {
		c := str[i]
		if isPqLetter(c) || isPqDigit(c) {
			b.WriteByte(c)
		} else {
			b.WriteString(strconv.Itoa(int(c)))
		}
	}
	name := b.String()
	c := name[0]
	if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') {
		return strings.ToUpper(name[0:1]) + name[1:]
	}
	return "PARGO_PREFIX_" + name
}

func importParquet(name string) (*Imported, error) {
	f, err := os.Open(name)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	if _, err := f.Seek(-8, io.SeekEnd); err != nil {
		return nil, err
	}
	data, err := io.ReadAll(&readerAt{f})
	if err != nil {
		return nil, err
	}
	rows, err := readParquet(data)
	if err != nil {
		return nil, err
	}
	w := NewRowsWriter()
	for _, r := range rows {
		if err := w.WriteRow(r); err != nil {
			return nil, err
		}
	}
	return finishImport(w.Bytes())
}

type readerAt struct{ f *os.File }

func (r *readerAt) Read(p []byte) (int, error) { return 0, io.EOF }

func readParquet(_ []byte) ([]*OrderedMap, error) {
	return nil, errors.New("unreachable")
}

func init() {
	parquetReadImpl = readParquetFile
}

var parquetReadImpl func(path string) ([]*OrderedMap, error)

func readParquetFile(path string) ([]*OrderedMap, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	if len(data) < 12 || string(data[len(data)-4:]) != "PAR1" {
		return nil, errors.New("invalid parquet file")
	}
	flen := int(binary.LittleEndian.Uint32(data[len(data)-8:]))
	if flen <= 0 || flen > len(data)-8 {
		return nil, errors.New("invalid parquet footer")
	}
	tr := &thriftReader{b: data[len(data)-8-flen : len(data)-8]}
	meta, err := tr.readStruct()
	if err != nil {
		return nil, err
	}
	schemaList := meta.list(2)
	if len(schemaList) == 0 {
		return nil, errors.New("parquet: empty schema")
	}
	pos := 0
	var leaves []*pqNode
	var build func(depthDef, depthRep int) *pqNode
	build = func(depthDef, depthRep int) *pqNode {
		se := schemaList[pos].(tStruct)
		pos++
		n := &pqNode{
			name:       se.str(4),
			repetition: se.int(3, 0),
			physType:   se.int(1, -1),
			typeLen:    se.int(2, 0),
			convType:   se.int(6, -1),
			leafIdx:    -1,
		}
		n.exName = pqVariableName(n.name)
		def, rep := depthDef, depthRep
		if n.repetition == 1 {
			def++
		} else if n.repetition == 2 {
			def++
			rep++
		}
		n.defLevel = def
		n.repLevel = rep
		nc := int(se.int(5, 0))
		if nc > 0 || !se.has(1) {
			for i := 0; i < nc && pos < len(schemaList); i++ {
				n.children = append(n.children, build(def, rep))
			}
		} else {
			n.leafIdx = len(leaves)
			n.maxDef = def
			n.maxRep = rep
			leaves = append(leaves, n)
		}
		return n
	}
	root := schemaList[0].(tStruct)
	pos = 1
	rootNode := &pqNode{name: root.str(4), leafIdx: -1}
	nc := int(root.int(5, 0))
	for i := 0; i < nc && pos < len(schemaList); i++ {
		rootNode.children = append(rootNode.children, build(0, 0))
	}

	var rows []*OrderedMap
	for _, rgi := range meta.list(4) {
		rg := rgi.(tStruct)
		numRows := int(rg.int(3, 0))
		cols := rg.list(1)
		triples := make([][]pqTriple, len(leaves))
		for ci, cci := range cols {
			if ci >= len(leaves) {
				break
			}
			cc := cci.(tStruct)
			md := cc.strct(3)
			if md == nil {
				return nil, errors.New("parquet: missing column metadata")
			}
			t, err := readColumnChunk(data, md, leaves[ci])
			if err != nil {
				return nil, err
			}
			triples[ci] = t
		}
		// split per row
		cursors := make([]int, len(leaves))
		for r := 0; r < numRows; r++ {
			rowTriples := make([][]pqTriple, len(leaves))
			for li := range leaves {
				ts := triples[li]
				c := cursors[li]
				if c >= len(ts) {
					continue
				}
				end := c + 1
				for end < len(ts) && ts[end].rep != 0 {
					end++
				}
				rowTriples[li] = ts[c:end]
				cursors[li] = end
			}
			row := NewOrderedMap()
			for _, child := range rootNode.children {
				row.Set(child.exName, assembleNode(child, rowTriples))
			}
			rows = append(rows, row)
		}
	}
	return rows, nil
}

func collectLeaves(n *pqNode, out *[]int) {
	if n.leafIdx >= 0 {
		*out = append(*out, n.leafIdx)
		return
	}
	for _, c := range n.children {
		collectLeaves(c, out)
	}
}

// assembleNode builds a value for node n from the triples of one parent instance.
func assembleNode(n *pqNode, tr [][]pqTriple) interface{} {
	var lv []int
	collectLeaves(n, &lv)
	if len(lv) == 0 {
		return nil
	}
	first := tr[lv[0]]
	if n.repetition == 2 {
		if len(first) == 0 || first[0].def < n.defLevel {
			return []interface{}{}
		}
		// split into elements
		var elems []interface{}
		starts := map[int][]int{}
		for _, l := range lv {
			ts := tr[l]
			var s []int
			for i := range ts {
				if i == 0 || ts[i].rep <= n.repLevel {
					s = append(s, i)
				}
			}
			starts[l] = s
		}
		count := len(starts[lv[0]])
		for e := 0; e < count; e++ {
			sub := make([][]pqTriple, len(tr))
			for _, l := range lv {
				s := starts[l]
				if e >= len(s) {
					continue
				}
				end := len(tr[l])
				if e+1 < len(s) {
					end = s[e+1]
				}
				sub[l] = tr[l][s[e]:end]
			}
			elems = append(elems, assembleSingle(n, sub))
		}
		return elems
	}
	return assembleSingle(n, tr)
}

func assembleSingle(n *pqNode, tr [][]pqTriple) interface{} {
	if n.leafIdx >= 0 {
		ts := tr[n.leafIdx]
		if len(ts) == 0 {
			return nil
		}
		if ts[0].def < n.maxDef {
			return nil
		}
		return ts[0].val
	}
	var lv []int
	collectLeaves(n, &lv)
	if n.repetition == 1 {
		ts := tr[lv[0]]
		if len(ts) == 0 || ts[0].def < n.defLevel {
			return nil
		}
	}
	m := NewOrderedMap()
	for _, c := range n.children {
		m.Set(c.exName, assembleNode(c, tr))
	}
	return m
}

func decompress(codec int64, src []byte, uncompressedSize int) ([]byte, error) {
	switch codec {
	case 0:
		return src, nil
	case 1:
		return snappyDecode(src)
	case 2:
		zr, err := gzip.NewReader(bytes.NewReader(src))
		if err != nil {
			return nil, err
		}
		return io.ReadAll(zr)
	}
	return nil, fmt.Errorf("unsupported compression codec: %d", codec)
}

func readColumnChunk(data []byte, md tStruct, leaf *pqNode) ([]pqTriple, error) {
	codec := md.int(4, 0)
	numValues := int(md.int(5, 0))
	off := md.int(9, 0)
	if md.has(11) {
		d := md.int(11, 0)
		if d > 0 && d < off {
			off = d
		}
	}
	end := off + md.int(7, 0)
	if off < 0 || int(end) > len(data) {
		return nil, errors.New("parquet: column chunk out of range")
	}
	var dict []interface{}
	var out []pqTriple
	pos := int(off)
	for pos < int(end) && len(out) < numValues {
		tr := &thriftReader{b: data, pos: pos}
		ph, err := tr.readStruct()
		if err != nil {
			return nil, err
		}
		pos = tr.pos
		csize := int(ph.int(3, 0))
		usize := int(ph.int(2, 0))
		if pos+csize > len(data) {
			return nil, errors.New("parquet: page out of range")
		}
		page := data[pos : pos+csize]
		pos += csize
		switch ph.int(1, 0) {
		case 2: // dictionary
			dh := ph.strct(7)
			raw, err := decompress(codec, page, usize)
			if err != nil {
				return nil, err
			}
			n := int(dh.int(1, 0))
			vals, _, err := decodePlain(raw, leaf, n)
			if err != nil {
				return nil, err
			}
			dict = vals
		case 0: // data page v1
			dh := ph.strct(5)
			raw, err := decompress(codec, page, usize)
			if err != nil {
				return nil, err
			}
			n := int(dh.int(1, 0))
			enc := dh.int(2, 0)
			p := 0
			reps := make([]int, n)
			defs := make([]int, n)
			if leaf.maxRep > 0 {
				l := int(binary.LittleEndian.Uint32(raw[p:]))
				p += 4
				reps = decodeRLELevels(raw[p:p+l], bitWidth(leaf.maxRep), n)
				p += l
			}
			if leaf.maxDef > 0 {
				l := int(binary.LittleEndian.Uint32(raw[p:]))
				p += 4
				defs = decodeRLELevels(raw[p:p+l], bitWidth(leaf.maxDef), n)
				p += l
			}
			t, err := buildTriples(raw[p:], enc, leaf, reps, defs, dict)
			if err != nil {
				return nil, err
			}
			out = append(out, t...)
		case 3: // data page v2
			dh := ph.strct(8)
			n := int(dh.int(1, 0))
			enc := dh.int(4, 0)
			dl := int(dh.int(5, 0))
			rl := int(dh.int(6, 0))
			compressed := dh.bool(7, true)
			reps := make([]int, n)
			defs := make([]int, n)
			if leaf.maxRep > 0 && rl > 0 {
				reps = decodeRLELevels(page[:rl], bitWidth(leaf.maxRep), n)
			}
			if leaf.maxDef > 0 && dl > 0 {
				defs = decodeRLELevels(page[rl:rl+dl], bitWidth(leaf.maxDef), n)
			}
			body := page[rl+dl:]
			if compressed {
				body, err = decompress(codec, body, usize-rl-dl)
				if err != nil {
					return nil, err
				}
			}
			t, err := buildTriples(body, enc, leaf, reps, defs, dict)
			if err != nil {
				return nil, err
			}
			out = append(out, t...)
		}
	}
	return out, nil
}

func bitWidth(max int) int {
	w := 0
	for max > 0 {
		w++
		max >>= 1
	}
	return w
}

func decodeRLELevels(b []byte, width, n int) []int {
	out := make([]int, 0, n)
	vals := decodeRLEHybrid(b, width, n)
	for _, v := range vals {
		out = append(out, int(v))
	}
	for len(out) < n {
		out = append(out, 0)
	}
	return out
}

func decodeRLEHybrid(b []byte, width, n int) []uint64 {
	out := make([]uint64, 0, n)
	p := 0
	byteWidth := (width + 7) / 8
	for len(out) < n && p < len(b) {
		h, k := binary.Uvarint(b[p:])
		if k <= 0 {
			break
		}
		p += k
		if h&1 == 0 {
			count := int(h >> 1)
			var v uint64
			for i := 0; i < byteWidth && p+i < len(b); i++ {
				v |= uint64(b[p+i]) << (8 * i)
			}
			p += byteWidth
			for i := 0; i < count && len(out) < n; i++ {
				out = append(out, v)
			}
		} else {
			groups := int(h >> 1)
			total := groups * 8
			nbytes := groups * width
			end := p + nbytes
			if end > len(b) {
				end = len(b)
			}
			chunk := b[p:end]
			p = end
			var bitPos uint
			for i := 0; i < total && len(out) < n; i++ {
				var v uint64
				for j := 0; j < width; j++ {
					byteIdx := int((bitPos + uint(j)) / 8)
					if byteIdx < len(chunk) && chunk[byteIdx]&(1<<((bitPos+uint(j))%8)) != 0 {
						v |= 1 << uint(j)
					}
				}
				bitPos += uint(width)
				out = append(out, v)
			}
		}
	}
	return out
}

func buildTriples(body []byte, enc int64, leaf *pqNode, reps, defs []int, dict []interface{}) ([]pqTriple, error) {
	n := len(defs)
	nonNull := 0
	for _, d := range defs {
		if d == leaf.maxDef {
			nonNull++
		}
	}
	var vals []interface{}
	var err error
	switch enc {
	case 0:
		vals, _, err = decodePlain(body, leaf, nonNull)
	case 2, 8:
		if len(body) == 0 {
			break
		}
		width := int(body[0])
		idx := decodeRLEHybrid(body[1:], width, nonNull)
		vals = make([]interface{}, len(idx))
		for i, ix := range idx {
			if int(ix) < len(dict) {
				vals[i] = dict[ix]
			}
		}
	case 3:
		if leaf.physType == 0 {
			// boolean RLE with 4-byte length prefix
			b := body
			if len(b) >= 4 {
				l := int(binary.LittleEndian.Uint32(b))
				if 4+l <= len(b) {
					b = b[4 : 4+l]
				} else {
					b = b[4:]
				}
			}
			bv := decodeRLEHybrid(b, 1, nonNull)
			for _, v := range bv {
				vals = append(vals, v == 1)
			}
		}
	case 5:
		ints := decodeDeltaBinaryPacked(body, nonNull)
		for _, v := range ints {
			if leaf.physType == 1 {
				vals = append(vals, int32(v))
			} else {
				vals = append(vals, v)
			}
		}
	case 6:
		vals = decodeDeltaLengthByteArray(body, nonNull)
	case 7:
		vals = decodeDeltaByteArray(body, nonNull)
	default:
		return nil, fmt.Errorf("unsupported encoding: %d", enc)
	}
	if err != nil {
		return nil, err
	}
	out := make([]pqTriple, n)
	vi := 0
	for i := 0; i < n; i++ {
		out[i].rep = reps[i]
		out[i].def = defs[i]
		if defs[i] == leaf.maxDef {
			if vi < len(vals) {
				out[i].val = vals[vi]
			}
			vi++
		}
	}
	return out, nil
}

func decodePlain(b []byte, leaf *pqNode, n int) ([]interface{}, int, error) {
	vals := make([]interface{}, 0, n)
	p := 0
	switch leaf.physType {
	case 0:
		for i := 0; i < n; i++ {
			byteIdx := i / 8
			if byteIdx >= len(b) {
				break
			}
			vals = append(vals, b[byteIdx]&(1<<(uint(i)%8)) != 0)
		}
		p = (n + 7) / 8
	case 1:
		for i := 0; i < n && p+4 <= len(b); i++ {
			vals = append(vals, int32(binary.LittleEndian.Uint32(b[p:])))
			p += 4
		}
	case 2:
		for i := 0; i < n && p+8 <= len(b); i++ {
			vals = append(vals, int64(binary.LittleEndian.Uint64(b[p:])))
			p += 8
		}
	case 3:
		for i := 0; i < n && p+12 <= len(b); i++ {
			vals = append(vals, string(b[p:p+12]))
			p += 12
		}
	case 4:
		for i := 0; i < n && p+4 <= len(b); i++ {
			vals = append(vals, math.Float32frombits(binary.LittleEndian.Uint32(b[p:])))
			p += 4
		}
	case 5:
		for i := 0; i < n && p+8 <= len(b); i++ {
			vals = append(vals, math.Float64frombits(binary.LittleEndian.Uint64(b[p:])))
			p += 8
		}
	case 6:
		for i := 0; i < n && p+4 <= len(b); i++ {
			l := int(binary.LittleEndian.Uint32(b[p:]))
			p += 4
			if p+l > len(b) {
				return nil, p, errors.New("parquet: byte array out of range")
			}
			vals = append(vals, string(b[p:p+l]))
			p += l
		}
	case 7:
		l := int(leaf.typeLen)
		for i := 0; i < n && p+l <= len(b); i++ {
			vals = append(vals, string(b[p:p+l]))
			p += l
		}
	}
	return vals, p, nil
}

func decodeDeltaBinaryPacked(b []byte, n int) []int64 {
	vals, _ := decodeDeltaBinaryPackedN(b, n)
	return vals
}

func decodeDeltaBinaryPackedN(b []byte, want int) ([]int64, int) {
	p := 0
	blockSize, k := binary.Uvarint(b[p:])
	if k <= 0 {
		return nil, 0
	}
	p += k
	miniBlocks, k := binary.Uvarint(b[p:])
	p += k
	total, k := binary.Uvarint(b[p:])
	p += k
	first, k := binary.Varint(b[p:])
	p += k
	out := []int64{}
	if total == 0 {
		return out, p
	}
	out = append(out, first)
	last := first
	perMini := int(blockSize / miniBlocks)
	for uint64(len(out)) < total && p < len(b) {
		minDelta, k := binary.Varint(b[p:])
		p += k
		widths := b[p : p+int(miniBlocks)]
		p += int(miniBlocks)
		for mb := 0; mb < int(miniBlocks) && uint64(len(out)) < total; mb++ {
			w := int(widths[mb])
			nbytes := perMini * w / 8
			chunk := b[p:min(p+nbytes, len(b))]
			p += nbytes
			var bitPos uint
			for i := 0; i < perMini && uint64(len(out)) < total; i++ {
				var v uint64
				for j := 0; j < w; j++ {
					byteIdx := int((bitPos + uint(j)) / 8)
					if byteIdx < len(chunk) && chunk[byteIdx]&(1<<((bitPos+uint(j))%8)) != 0 {
						v |= 1 << uint(j)
					}
				}
				bitPos += uint(w)
				last = last + minDelta + int64(v)
				out = append(out, last)
			}
		}
	}
	return out, p
}

func decodeDeltaLengthByteArray(b []byte, n int) []interface{} {
	lens, p := decodeDeltaBinaryPackedN(b, n)
	var out []interface{}
	for _, l := range lens {
		if p+int(l) > len(b) {
			break
		}
		out = append(out, string(b[p:p+int(l)]))
		p += int(l)
	}
	return out
}

func decodeDeltaByteArray(b []byte, n int) []interface{} {
	prefixes, p := decodeDeltaBinaryPackedN(b, n)
	suffixes := decodeDeltaLengthByteArray(b[p:], n)
	var out []interface{}
	prev := ""
	for i := range suffixes {
		pl := 0
		if i < len(prefixes) {
			pl = int(prefixes[i])
		}
		if pl > len(prev) {
			pl = len(prev)
		}
		s := prev[:pl] + suffixes[i].(string)
		out = append(out, s)
		prev = s
	}
	return out
}
