func cellNameToCoords(ref string) (int, int, bool) {
	col := 0
	i := 0
	for i < len(ref) {
		c := ref[i]
		if c >= 'a' && c <= 'z' {
			c -= 32
		}
		if c < 'A' || c > 'Z' {
			break
		}
		col = col*26 + int(c-'A'+1)
		i++
	}
	if i == 0 || i == len(ref) {
		return 0, 0, false
	}
	row, err := strconv.Atoi(ref[i:])
	if err != nil {
		return 0, 0, false
	}
	return col, row, true
}

func isNumericExcel(s string) (bool, int) {
	dot, e, n, p := false, false, false, 0
	for i, v := range s {
		if v == '.' {
			if dot {
				return false, 0
			}
			dot = true
		} else if v == 'E' || v == 'e' {
			e = true
		} else if v < '0' || v > '9' {
			if i == 0 && v == '-' {
				continue
			}
			if e && v == '-' {
				return true, 0
			}
			if e && v == '+' {
				p = 15
				continue
			}
			return false, 0
		} else {
			p++
		}
		n = true
	}
	return n, p
}

func roundPrecisionExcel(text string, prec int, fmtc byte) string {
	decimal := big.Float{}
	if _, ok := decimal.SetString(text); ok {
		flt, _ := decimal.Float64()
		return strconv.FormatFloat(flt, fmtc, prec, 64)
	}
	return text
}

func (x *xlsxFile) cellValue(c *xlsxCell) string {
	switch c.T {
	case "b":
		if c.V == "1" {
			return "TRUE"
		}
		if c.V == "0" {
			return "FALSE"
		}
		return x.formattedValue(c.S, c.V)
	case "s":
		if c.V != "" {
			idx, _ := strconv.Atoi(c.V)
			if idx >= 0 && idx < len(x.sst) {
				return x.formattedValue(c.S, x.sst[idx])
			}
		}
		return x.formattedValue(c.S, c.V)
	case "str":
		return x.formattedValue(c.S, c.V)
	case "inlineStr":
		if c.IS != nil {
			return x.formattedValue(c.S, c.IS.String())
		}
		return x.formattedValue(c.S, c.V)
	}
	v := c.V
	if isNum, precision := isNumericExcel(v); isNum {
		if precision == 0 {
			v = roundPrecisionExcel(v, -1, 'f')
		} else if precision > 15 {
			v = roundPrecisionExcel(v, 15, 'G')
		} else {
			v = roundPrecisionExcel(v, -1, 'G')
		}
	}
	return x.formattedValue(c.S, v)
}

var builtInNumFmt = map[int]string{
	0: "general", 1: "0", 2: "0.00", 3: "#,##0", 4: "#,##0.00", 9: "0%", 10: "0.00%",
	11: "0.00e+00", 12: "# ?/?", 13: "# ??/??", 14: "mm-dd-yy", 15: "d-mmm-yy", 16: "d-mmm",
