func (x *xlsxFile) formattedValue(s int, v string) string {
	if s == 0 {
		return v
	}
	if s >= len(x.styles.CellXfs) {
		return v
	}
	numFmtID := 0
	if x.styles.CellXfs[s].NumFmtID != nil {
		numFmtID = *x.styles.CellXfs[s].NumFmtID
	}
	switch numFmtID {
	case 1, 3:
		f, err := strconv.ParseFloat(v, 64)
		if err != nil {
			return v
		}
		return fmt.Sprintf("%d", int64(f))
	case 2, 4:
		f, err := strconv.ParseFloat(v, 64)
		if err != nil {
			return v
		}
		return fmt.Sprintf("%.2f", f)
	case 9:
		f, err := strconv.ParseFloat(v, 64)
		if err != nil {
			return v
		}
		return fmt.Sprintf("%.f%%", f*100)
	case 10:
		f, err := strconv.ParseFloat(v, 64)
		if err != nil {
			return v
		}
		return fmt.Sprintf("%.2f%%", f*100)
	case 11, 48:
		f, err := strconv.ParseFloat(v, 64)
		if err != nil {
			return v
		}
		return fmt.Sprintf("%.2E", f)
	case 37, 38:
		f, err := strconv.ParseFloat(v, 64)
		if err != nil {
			return v
		}
		if f < 0 {
			return fmt.Sprintf("(%d)", int64(-f))
		}
		return fmt.Sprintf("%d", int64(f))
	case 39, 40:
		f, err := strconv.ParseFloat(v, 64)
		if err != nil {
			return v
		}
		if f < 0 {
			return fmt.Sprintf("(%.2f)", f)
		}
		return fmt.Sprintf("%.2f", f)
	}
	if code, ok := builtInNumFmt[numFmtID]; ok {
		return excelFormat(v, code, x.date1904)
	}
	for _, nf := range x.styles.NumFmts {
		if nf.ID == numFmtID {
			return excelFormat(v, nf.Code, x.date1904)
		}
	}
	return v
}

// ---- number format (date/time subset) ----

type nfToken struct {
	kind string // "lit", "date", "ampm", "elapsed", "unsupported", "general", "text"
	val  string
}

func tokenizeNumFmt(section string) []nfToken {
	var toks []nfToken
	i := 0
	n := len(section)
	for i < n {
		c := section[i]
		switch {
		case c == '"':
			j := i + 1
			for j < n && section[j] != '"' {
				j++
			}
			toks = append(toks, nfToken{"lit", section[i+1 : min(j, n)]})
			i = j + 1
		case c == '\\':
			if i+1 < n {
				_, sz := decodeRuneStr(section[i+1:])
				toks = append(toks, nfToken{"lit", section[i+1 : i+1+sz]})
				i += 1 + sz
			} else {
				i++
			}
		case c == '[':
			j := i + 1
			for j < n && section[j] != ']' {
				j++
			}
			inner := section[i+1 : min(j, n)]
			lu := strings.ToLower(inner)
			if lu == "h" || lu == "hh" || lu == "m" || lu == "mm" || lu == "s" || lu == "ss" {
				toks = append(toks, nfToken{"elapsed", lu})
			}
			i = j + 1
		case c == '_' || c == '*':
			// padding/fill: skip next char
			i += 2
		case c == 'y' || c == 'Y' || c == 'm' || c == 'M' || c == 'd' || c == 'D' || c == 'h' || c == 'H' || c == 's' || c == 'S':
			lc := c | 0x20
			j := i
			for j < n && section[j]|0x20 == lc {
				j++
			}
			toks = append(toks, nfToken{"date", strings.ToLower(section[i:j])})
			i = j
		case c == 'A' || c == 'a':
			rest := section[i:]
			if len(rest) >= 5 && strings.EqualFold(rest[:5], "am/pm") {
				toks = append(toks, nfToken{"ampm", rest[:5]})
				i += 5
			} else if len(rest) >= 3 && strings.EqualFold(rest[:3], "a/p") {
				toks = append(toks, nfToken{"ampm", rest[:3]})
				i += 3
			} else {
				toks = append(toks, nfToken{"unsupported", string(c)})
				i++
			}
		case c == 'G' || c == 'g':
			if len(section)-i >= 7 && strings.EqualFold(section[i:i+7], "general") {
				toks = append(toks, nfToken{"general", ""})
				i += 7
			} else {
				toks = append(toks, nfToken{"unsupported", string(c)})
				i++
			}
		case c == '0' || c == '#' || c == '?' || c == '.' || c == ',' || c == '%' || c == 'E' || c == 'e':
			toks = append(toks, nfToken{"unsupported", string(c)})
			i++
		case c == '@':
			toks = append(toks, nfToken{"text", "@"})
			i++
		default:
			_, sz := decodeRuneStr(section[i:])
			toks = append(toks, nfToken{"lit", section[i : i+sz]})
			i += sz
		}
	}
	return toks
}

func decodeRuneStr(s string) (rune, int) {
	for i, r := range s {
		_ = i
		return r, len(string(r))
	}
	return 0, 1
}

func splitSections(code string) []string {
	var secs []string
	inQ := false
	start := 0
	for i := 0; i < len(code); i++ {
		c := code[i]
		if c == '"' {
			inQ = !inQ
		} else if c == '\\' {
			i++
		} else if c == ';' && !inQ {
			secs = append(secs, code[start:i])
			start = i + 1
		}
	}
	secs = append(secs, code[start:])
	return secs
}

var excel1900Epoc = time.Date(1899, time.December, 30, 0, 0, 0, 0, time.UTC)
var excel1904Epoc = time.Date(1904, time.January, 1, 0, 0, 0, 0, time.UTC)

func timeFromExcel(f float64, date1904 bool) time.Time {
	whole := int(f)
	frac := f - float64(whole)
	date := excel1900Epoc
	if date1904 {
		date = excel1904Epoc
	}
	dur := time.Duration(86400000000000 * frac)
	return date.AddDate(0, 0, whole).Add(dur)
}

func excelFormat(value, code string, date1904 bool) string {
	f, err := strconv.ParseFloat(value, 64)
	if err != nil {
		return value
	}
	if f <= 0 {
		return value
	}
	secs := splitSections(code)
	toks := tokenizeNumFmt(secs[0])
	hasDate := false
	for _, t := range toks {
		switch t.kind {
		case "unsupported", "general", "text":
			return value
		case "date", "elapsed", "ampm":
			hasDate = true
		}
	}
	if !hasDate {
		var b strings.Builder
		for _, t := range toks {
			b.WriteString(t.val)
		}
		return b.String()
	}
	t := timeFromExcel(f, date1904)
	hasAmPm := false
	for _, tk := range toks {
		if tk.kind == "ampm" {
			hasAmPm = true
		}
	}
	hour := t.Hour()
	pm := false
	if hasAmPm && hour > 12 {
		hour -= 12
		pm = true
	}
	var b strings.Builder
	// find index of previous/next date tokens for m disambiguation
	dateIdx := []int{}
	for i, tk := range toks {
		if tk.kind == "date" || tk.kind == "elapsed" {
			dateIdx = append(dateIdx, i)
		}
	}
	prevDate := func(i int) string {
		for k := len(dateIdx) - 1; k >= 0; k-- {
			if dateIdx[k] < i {
				return toks[dateIdx[k]].val
			}
		}
		return ""
	}
	nextDate := func(i int) string {
		for _, k := range dateIdx {
			if k > i {
				return toks[k].val
			}
		}
		return ""
	}
	for i, tk := range toks {
		switch tk.kind {
		case "lit":
			b.WriteString(tk.val)
		case "ampm":
			parts := strings.Split(tk.val, "/")
			if pm {
				b.WriteString(parts[1])
			} else {
				b.WriteString(parts[0])
			}
		case "elapsed":
			switch tk.val[0] {
			case 'h':
				b.WriteString(fmt.Sprintf("%.f", f*24))
			case 'm':
				b.WriteString(fmt.Sprintf("%.f", f*24*60))
			case 's':
				b.WriteString(fmt.Sprintf("%.f", f*24*60*60))
			}
		case "date":
			v := tk.val
			l := len(v)
			switch v[0] {
			case 'y':
				ys := strconv.Itoa(t.Year())
				if l <= 2 {
					if len(ys) > 2 {
						b.WriteString(ys[2:])
					}
				} else {
					b.WriteString(ys)
				}
			case 'm':
				p := prevDate(i)
				nx := nextDate(i)
				isMinute := (l <= 2) && ((p != "" && (p[0] == 'h')) || (nx != "" && nx[0] == 's'))
				if isMinute {
					if l == 1 {
						b.WriteString(strconv.Itoa(t.Minute()))
					} else {
						b.WriteString(fmt.Sprintf("%02d", t.Minute()))
					}
				} else {
					switch {
					case l == 1:
						b.WriteString(strconv.Itoa(int(t.Month())))
					case l == 2:
						b.WriteString(fmt.Sprintf("%02d", int(t.Month())))
					case l == 3:
						b.WriteString(t.Month().String()[:3])
					case l == 5:
						b.WriteString(t.Month().String()[:1])
					default:
						b.WriteString(t.Month().String())
					}
				}
			case 'd':
				switch {
				case l == 1:
					b.WriteString(strconv.Itoa(t.Day()))
				case l == 2:
					b.WriteString(fmt.Sprintf("%02d", t.Day()))
				case l == 3:
					b.WriteString(t.Weekday().String()[:3])
				default:
					b.WriteString(t.Weekday().String())
				}
			case 'h':
				if l == 1 {
					b.WriteString(strconv.Itoa(hour))
				} else {
					b.WriteString(fmt.Sprintf("%02d", hour))
				}
			case 's':
				if l == 1 {
					b.WriteString(strconv.Itoa(t.Second()))
				} else {
					b.WriteString(fmt.Sprintf("%02d", t.Second()))
				}
			}
		}
	}
	return b.String()
}

var _ = math.Abs

// ---- reading ----

func openXLSX(name string) (*xlsxFile, error) {
	data, err := readInput(name)
	if err != nil {
		return nil, err
	}
	zr, err := zip.NewReader(bytes.NewReader(data), int64(len(data)))
	if err != nil {
		return nil, err
	}
	x := &xlsxFile{zr: zr, files: map[string]*zip.File{}}
	for _, f := range zr.File {
		x.files[strings.TrimPrefix(f.Name, "/")] = f
	}
	if b, _ := x.read("xl/sharedStrings.xml"); b != nil {
		var sst xlsxSST
		if err := xml.Unmarshal(b, &sst); err == nil {
			for _, si := range sst.SI {
				x.sst = append(x.sst, si.String())
			}
		}
	}
	if b, _ := x.read("xl/styles.xml"); b != nil {
		xml.Unmarshal(b, &x.styles)
	}
	return x, nil
}

type xlsxSheetRows struct {
	name string
	rows [][]string
}

func (x *xlsxFile) sheets() ([]xlsxSheetRows, error) {
	wbb, _ := x.read("xl/workbook.xml")
	var wb xlsxWorkbook
	if wbb != nil {
		if err := xml.Unmarshal(wbb, &wb); err != nil {
			return nil, fmt.Errorf("xml decode error: %v", err)
		}
	}
	x.date1904 = wb.WorkbookPr.Date1904 == "1" || wb.WorkbookPr.Date1904 == "true"
	relb, _ := x.read("xl/_rels/workbook.xml.rels")
	var rels xlsxRels
	if relb != nil {
		xml.Unmarshal(relb, &rels)
	}
	var out []xlsxSheetRows
	for i, s := range wb.Sheets {
		target := ""
		for _, r := range rels.Rels {
			if r.ID == s.RID {
				target = r.Target
			}
		}
		var p string
		if target == "" {
			p = fmt.Sprintf("xl/worksheets/sheet%d.xml", i+1)
		} else if strings.HasPrefix(target, "/") {
			p = strings.TrimPrefix(target, "/")
		} else {
			p = path.Join("xl", target)
		}
		b, err := x.read(p)
		if err != nil {
			return nil, err
		}
		rows, err := x.parseSheet(b)
		if err != nil {
			return nil, err
		}
		out = append(out, xlsxSheetRows{name: s.Name, rows: rows})
	}
	return out, nil
}

func (x *xlsxFile) parseSheet(b []byte) ([][]string, error) {
	if b == nil {
		return nil, nil
	}
	dec := xml.NewDecoder(bytes.NewReader(b))
	var results [][]string
	curRow := 0
	var cols []string
	inRow := false
	cellCol := 0
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		switch t := tok.(type) {
		case xml.StartElement:
			switch t.Name.Local {
			case "row":
				rowNum := curRow + 1
				for _, a := range t.Attr {
					if a.Name.Local == "r" {
						if n, err := strconv.Atoi(a.Value); err == nil {
							rowNum = n
						}
					}
				}
				for curRow+1 < rowNum {
					results = append(results, []string{})
					curRow++
				}
				curRow = rowNum
				cols = []string{}
				inRow = true
				cellCol = 0
			case "c":
				if !inRow {
					dec.Skip()
					continue
				}
				var c xlsxCell
				if err := dec.DecodeElement(&c, &t); err != nil {
					return nil, err
				}
				cellCol++
				if c.R != "" {
					if col, _, ok := cellNameToCoords(c.R); ok {
						cellCol = col
					}
				}
				val := x.cellValue(&c)
				if val != "" || c.F != nil {
					for len(cols) < cellCol-1 {
						cols = append(cols, "")
					}
					cols = append(cols, val)
				}
			}
		case xml.EndElement:
			if t.Name.Local == "row" && inRow {
				results = append(results, cols)
				inRow = false
			}
		}
	}
	max := 0
	for i, r := range results {
		if len(r) > 0 {
			max = i + 1
		}
	}
	return results[:max], nil
}

func importExcel(name string) (*Imported, error) {
	x, err := openXLSX(name)
	if err != nil {
		return nil, err
	}
	sheets, err := x.sheets()
	if err != nil {
		return nil, err
	}
	row := NewOrderedMap()
	writeSheet := func(rows [][]string) ([]byte, error) {
		w := NewRowsWriter()
		if len(rows) == 0 {
			return w.Bytes(), nil
		}
		var header []string
		for i, h := range rows[0] {
			if h == "" {
				h = columnLetter(i)
			}
			header = append(header, h)
		}
		for _, r := range rows[1:] {
			for i := len(header); i < len(r); i++ {
				header = append(header, columnLetter(i))
			}
			for i, h := range header {
				if i < len(r) {
					row.Set(h, r[i])
				} else {
					row.Set(h, nil)
				}
			}
			if err := w.WriteRow(row); err != nil {
				return nil, err
			}
		}
		return w.Bytes(), nil
	}
	if len(sheets) == 1 {
		b, err := writeSheet(sheets[0].rows)
		if err != nil {
			return nil, err
		}
		return finishImport(b)
	}
	var buf bytes.Buffer
	buf.WriteString("{")
	for i, s := range sheets {
		if i > 0 {
			buf.WriteString(",")
		}
		b, err := writeSheet(s.rows)
		if err != nil {
			return nil, err
		}
		buf.WriteString(`"` + s.name + `": `)
		buf.Write(b)
	}
	buf.WriteString("}")
	return finishImport(buf.Bytes())
}
