	writeSheet := func(rows [][]string) ([]byte, error) {
		w := NewRowsWriter()
		if len(rows) == 0 {
			return w.Bytes(), nil
		}
		var header []string
		for i, h := range rows[0] {
			if h == "" {
				h = columnLetter(i)
			}
			header = append(header, h)
		}
		for _, r := range rows[1:] {
			for i := len(header); i < len(r); i++ {
				header = append(header, columnLetter(i))
			}
			for i, h := range header {
				if i < len(r) {
					row.Set(h, r[i])
				} else {
					row.Set(h, nil)
				}
			}
			if err := w.WriteRow(row); err != nil {
				return nil, err
			}
		}
		return w.Bytes(), nil
	}
	if len(tables) == 1 {
		b, err := writeSheet(tables[0].rows)
		if err != nil {
			return nil, err
		}
		return finishImport(b)
	}
	var buf bytes.Buffer
	buf.WriteString("{")
	for i, s := range tables {
		if i > 0 {
			buf.WriteString(",")
		}
		b, err := writeSheet(s.rows)
		if err != nil {
			return nil, err
		}
		buf.WriteString(`"` + s.name + `": `)
		buf.Write(b)
	}
	buf.WriteString("}")
	return finishImport(buf.Bytes())
}
