			if err != nil {
				return nil, err
			}
			u.branches = append(u.branches, s)
		}
		return u, nil
	case map[string]interface{}:
		typ, _ := t["type"].(string)
		if typ == "" {
			if inner, ok := t["type"]; ok {
				s, err := p.parse(inner, ns)
				if err != nil {
					return nil, err
				}
				return s, nil
			}
			return nil, errors.New("missing type")
		}
		logical, _ := t["logicalType"].(string)
		switch typ {
		case "record", "error", "enum", "fixed":
			name, _ := t["name"].(string)
			nsp, _ := t["namespace"].(string)
			if nsp == "" {
				nsp = ns
			}
			full := name
			if !strings.Contains(name, ".") && nsp != "" {
				full = nsp + "." + name
			}
			if idx := strings.LastIndex(full, "."); idx >= 0 {
				nsp = full[:idx]
			}
			s := &avroSchema{typ: typ, name: full, logical: logical}
			if typ == "error" {
				s.typ = "record"
			}
			p.named[full] = s
			switch typ {
			case "record", "error":
				fields, _ := t["fields"].([]interface{})
				for _, fi := range fields {
					fm, _ := fi.(map[string]interface{})
					fname, _ := fm["name"].(string)
					ft, err := p.parse(fm["type"], nsp)
					if err != nil {
						return nil, err
					}
					s.fields = append(s.fields, avroField{name: fname, typ: ft})
				}
			case "enum":
				syms, _ := t["symbols"].([]interface{})
				for _, sy := range syms {
					str, _ := sy.(string)
					s.symbols = append(s.symbols, str)
				}
			case "fixed":
				if sz, ok := t["size"].(float64); ok {
					s.size = int(sz)
				}
				if pr, ok := t["precision"].(float64); ok {
					s.precision = int(pr)
				}
				if sc, ok := t["scale"].(float64); ok {
					s.scale = int(sc)
				}
			}
			return s, nil
		case "array":
