	switch s.typ {
	case "null":
		return nil, nil
	case "boolean":
		if d.pos >= len(d.b) {
			return nil, errAvroShort
		}
		v := d.b[d.pos] != 0
		d.pos++
		return v, nil
	case "int":
		v, err := d.long()
		if err != nil {
			return nil, err
		}
		switch s.logical {
		case "date":
			return time.Unix(int64(v)*86400, 0).UTC(), nil
		case "time-millis":
			return time.Duration(v) * time.Millisecond, nil
		}
		return int32(v), nil
	case "long":
		v, err := d.long()
		if err != nil {
			return nil, err
		}
		switch s.logical {
		case "timestamp-millis":
			return time.Unix(0, 0).Add(time.Duration(v) * time.Millisecond).UTC(), nil
		case "timestamp-micros":
			return time.Unix(0, 0).Add(time.Duration(v) * time.Microsecond).UTC(), nil
		case "time-micros":
			return time.Duration(v) * time.Microsecond, nil
		}
		return v, nil
	case "float":
		if d.pos+4 > len(d.b) {
			return nil, errAvroShort
		}
		v := math.Float32frombits(binary.LittleEndian.Uint32(d.b[d.pos:]))
		d.pos += 4
		return v, nil
	case "double":
		if d.pos+8 > len(d.b) {
			return nil, errAvroShort
		}
		v := math.Float64frombits(binary.LittleEndian.Uint64(d.b[d.pos:]))
		d.pos += 8
		return v, nil
	case "bytes":
		b, err := d.bytes()
		if err != nil {
			return nil, err
		}
		if s.logical == "decimal" {
			return avroDecimal(b, s.scale), nil
		}
		return append([]byte{}, b...), nil
	case "string":
		b, err := d.bytes()
		if err != nil {
			return nil, err
		}
		return string(b), nil
	case "record":
		m := map[string]interface{}{}
		for _, f := range s.fields {
			v, err := d.decode(f.typ)
			if err != nil {
				return nil, err
			}
			m[f.name] = v
		}
		return m, nil
	case "enum":
		i, err := d.long()
		if err != nil {
			return nil, err
		}
		if i < 0 || int(i) >= len(s.symbols) {
			return nil, errors.New("enum index out of range")
		}
		return s.symbols[i], nil
	case "fixed":
		if d.pos+s.size > len(d.b) {
			return nil, errAvroShort
		}
		v := append([]byte{}, d.b[d.pos:d.pos+s.size]...)
		d.pos += s.size
		if s.logical == "decimal" {
			return avroDecimal(v, s.scale), nil
		}
		return v, nil
	case "array":
		var out []interface{}
		for {
			n, err := d.long()
			if err != nil {
				return nil, err
			}
			if n == 0 {
				break
			}
			if n < 0 {
				n = -n
				if _, err := d.long(); err != nil {
					return nil, err
				}
			}
			for i := int64(0); i < n; i++ {
				v, err := d.decode(s.items)
				if err != nil {
					return nil, err
				}
				out = append(out, v)
			}
		}
		if out == nil {
			out = []interface{}{}
		}
		return out, nil
	case "map":
		m := map[string]interface{}{}
		for {
			n, err := d.long()
			if err != nil {
				return nil, err
			}
			if n == 0 {
				break
			}
			if n < 0 {
				n = -n
				if _, err := d.long(); err != nil {
					return nil, err
				}
			}
			for i := int64(0); i < n; i++ {
				k, err := d.bytes()
				if err != nil {
					return nil, err
				}
				v, err := d.decode(s.values)
				if err != nil {
					return nil, err
				}
				m[string(k)] = v
			}
		}
		return m, nil
	case "union":
		i, err := d.long()
		if err != nil {
			return nil, err
		}
		if i < 0 || int(i) >= len(s.branches) {
			return nil, errors.New("union index out of range")
		}
		b := s.branches[i]
		v, err := d.decode(b)
		if err != nil {
			return nil, err
		}
		if b.typ == "null" {
			return nil, nil
		}
		return map[string]interface{}{avroTypeName(b): v}, nil
	}
	return nil, fmt.Errorf("unsupported avro type: %s", s.typ)
}

func avroDecimal(b []byte, scale int) *big.Rat {
	i := new(big.Int).SetBytes(b)
	if len(b) > 0 && b[0]&0x80 != 0 {
		i.Sub(i, new(big.Int).Lsh(big.NewInt(1), uint(len(b)*8)))
	}
	r := new(big.Rat).SetInt(i)
	if scale > 0 {
		r.Quo(r, new(big.Rat).SetInt(new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(scale)), nil)))
	}
	return r
}

func importAvro(name string) (*Imported, error) {
	data, err := readInput(name)
	if err != nil {
		return nil, err
	}
	if len(data) < 4 {
		return nil, errors.New("cannot create OCFReader: cannot read OCF header magic bytes: unexpected EOF")
	}
	if !bytes.Equal(data[:4], []byte("Obj\x01")) {
		return nil, fmt.Errorf("cannot create OCFReader: cannot read OCF header with invalid magic bytes: %q", data[:4])
	}
	d := &avroDecoder{b: data, pos: 4}
	meta := map[string][]byte{}
	for {
		n, err := d.long()
		if err != nil {
			return nil, errors.New("cannot create OCFReader: cannot read OCF header: " + err.Error())
		}
		if n == 0 {
			break
		}
		if n < 0 {
			n = -n
			d.long()
		}
		for i := int64(0); i < n; i++ {
			k, err := d.bytes()
			if err != nil {
				return nil, errors.New("cannot create OCFReader: " + err.Error())
			}
			v, err := d.bytes()
			if err != nil {
				return nil, errors.New("cannot create OCFReader: " + err.Error())
			}
			meta[string(k)] = v
		}
	}
	if d.pos+16 > len(data) {
		return nil, errors.New("cannot create OCFReader: cannot read OCF header sync marker: unexpected EOF")
	}
	sync := data[d.pos : d.pos+16]
	d.pos += 16
	var schemaJSON interface{}
	if err := json.Unmarshal(meta["avro.schema"], &schemaJSON); err != nil {
		return nil, errors.New("cannot create OCFReader: " + err.Error())
	}
	p := &avroParser{named: map[string]*avroSchema{}}
	schema, err := p.parse(schemaJSON, "")
	if err != nil {
		return nil, errors.New("cannot create OCFReader: " + err.Error())
	}
	codec := string(meta["avro.codec"])
	w := NewRowsWriter()
	for d.pos < len(data) {
		count, err := d.long()
		if err != nil {
			break
		}
		size, err := d.long()
		if err != nil || d.pos+int(size) > len(data) {
			return nil, errors.New("cannot read block")
		}
		block := data[d.pos : d.pos+int(size)]
		d.pos += int(size)
		switch codec {
		case "", "null":
		case "deflate":
			block, err = io.ReadAll(flate.NewReader(bytes.NewReader(block)))
			if err != nil {
				return nil, err
			}
		case "snappy":
			if len(block) < 4 {
				return nil, errors.New("snappy block too short")
			}
			block, err = snappyDecode(block[:len(block)-4])
			if err != nil {
				return nil, err
			}
		default:
			return nil, fmt.Errorf("cannot create OCFReader: unsupported codec: %s", codec)
		}
		if d.pos+16 <= len(data) && bytes.Equal(data[d.pos:d.pos+16], sync) {
			d.pos += 16
		}
		bd := &avroDecoder{b: block}
		for i := int64(0); i < count; i++ {
			v, err := bd.decode(schema)
			if err != nil {
				return nil, err
			}
			switch t := v.(type) {
			case map[string]interface{}:
				row := NewOrderedMap()
				for _, f := range schema.fields {
					row.Set(f.name, t[f.name])
				}
				if err := w.WriteRow(row); err != nil {
					return nil, err
				}
			default:
				if err := w.WriteValue(v); err != nil {
					return nil, err
				}
			}
		}
	}
	return finishImport(w.Bytes())
}
