package main

import (
	"strings"
)

// A small SQL tokenizer used to emulate the JSON -> and ->> operators
// (introduced in SQLite 3.38) on top of older SQLite versions.

type sqlTok struct {
	kind string // ws, comment, str, ident, qident, num, op, lparen, rparen, comma, other
	text string
}

func isIdentChar(c byte) bool {
	return c == '_' || c == '$' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c >= 0x80
}

func tokenizeSQL(s string) []sqlTok {
	var toks []sqlTok
	i := 0
	n := len(s)
	for i < n {
		c := s[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f':
			j := i
			for j < n && (s[j] == ' ' || s[j] == '\t' || s[j] == '\n' || s[j] == '\r' || s[j] == '\f') {
				j++
			}
			toks = append(toks, sqlTok{"ws", s[i:j]})
			i = j
		case c == '-' && i+1 < n && s[i+1] == '-':
			j := i
			for j < n && s[j] != '\n' {
				j++
			}
			toks = append(toks, sqlTok{"comment", s[i:j]})
			i = j
		case c == '/' && i+1 < n && s[i+1] == '*':
			j := strings.Index(s[i+2:], "*/")
			if j < 0 {
				toks = append(toks, sqlTok{"comment", s[i:]})
				i = n
			} else {
				toks = append(toks, sqlTok{"comment", s[i : i+2+j+2]})
				i = i + 2 + j + 2
			}
		case c == '\'' || c == '"' || c == '`':
			j := i + 1
			for j < n {
				if s[j] == c {
					if j+1 < n && s[j+1] == c {
						j += 2
						continue
					}
					break
				}
				j++
			}
			end := j + 1
			if end > n {
				end = n
			}
			kind := "str"
			if c != '\'' {
				kind = "qident"
			}
			toks = append(toks, sqlTok{kind, s[i:end]})
			i = end
		case c == '[':
			j := strings.IndexByte(s[i:], ']')
			if j < 0 {
				toks = append(toks, sqlTok{"qident", s[i:]})
				i = n
			} else {
				toks = append(toks, sqlTok{"qident", s[i : i+j+1]})
				i = i + j + 1
			}
		case (c == 'x' || c == 'X') && i+1 < n && s[i+1] == '\'':
			j := strings.IndexByte(s[i+2:], '\'')
			if j < 0 {
				toks = append(toks, sqlTok{"str", s[i:]})
				i = n
			} else {
				toks = append(toks, sqlTok{"str", s[i : i+2+j+1]})
				i = i + 2 + j + 1
			}
		case (c >= '0' && c <= '9') || (c == '.' && i+1 < n && s[i+1] >= '0' && s[i+1] <= '9'):
			j := i
			for j < n && (isIdentChar(s[j]) || s[j] == '.' || ((s[j] == '+' || s[j] == '-') && j > i && (s[j-1] == 'e' || s[j-1] == 'E'))) {
				j++
			}
			toks = append(toks, sqlTok{"num", s[i:j]})
			i = j
		case isIdentChar(c):
			j := i
			for j < n && isIdentChar(s[j]) {
				j++
			}
			toks = append(toks, sqlTok{"ident", s[i:j]})
			i = j
		case c == '(':
			toks = append(toks, sqlTok{"lparen", "("})
			i++
		case c == ')':
			toks = append(toks, sqlTok{"rparen", ")"})
			i++
		case c == ',':
			toks = append(toks, sqlTok{"comma", ","})
			i++
		default:
			// operators
			ops := []string{"->>", "->", "||", "<<", ">>", "<=", ">=", "==", "!=", "<>"}
			matched := false
			for _, op := range ops {
				if strings.HasPrefix(s[i:], op) {
					toks = append(toks, sqlTok{"op", op})
					i += len(op)
					matched = true
					break
				}
			}
			if !matched {
				toks = append(toks, sqlTok{"op", string(c)})
				i++
			}
		}
	}
	return toks
}

func isSignificant(t sqlTok) bool {
	return t.kind != "ws" && t.kind != "comment"
}

func prevSig(toks []sqlTok, i int) int {
	for j := i - 1; j >= 0; j-- {
		if isSignificant(toks[j]) {
			return j
		}
	}
	return -1
}

func nextSig(toks []sqlTok, i int) int {
	for j := i + 1; j < len(toks); j++ {
		if isSignificant(toks[j]) {
			return j
		}
	}
	return -1
}

var sqlKeywordsBeforeOperand = map[string]bool{
	"SELECT": true, "WHERE": true, "AND": true, "OR": true, "NOT": true, "ON": true, "BY": true,
	"WHEN": true, "THEN": true, "ELSE": true, "CASE": true, "AS": true, "IN": true, "IS": true,
	"LIKE": true, "GLOB": true, "HAVING": true, "DISTINCT": true, "ALL": true, "RETURN": true,
	"FROM": true, "JOIN": true, "SET": true, "VALUES": true, "LIMIT": true, "OFFSET": true,
	"BETWEEN": true, "REGEXP": true, "MATCH": true, "ESCAPE": true,
}

// termStart finds the start index of the term ending at token index end.
func termStart(toks []sqlTok, end int) int {
	t := toks[end]
	start := end
	switch t.kind {
	case "rparen":
		depth := 0
		j := end
		for ; j >= 0; j-- {
			if toks[j].kind == "rparen" {
				depth++
			} else if toks[j].kind == "lparen" {
				depth--
				if depth == 0 {
					break
				}
			}
		}
		if j < 0 {
			return end
		}
		start = j
		// function call name before '('
		if p := prevSig(toks, start); p >= 0 && (toks[p].kind == "ident" || toks[p].kind == "qident") && !sqlKeywordsBeforeOperand[strings.ToUpper(toks[p].text)] {
			start = p
		}
	case "ident", "qident":
		if strings.ToUpper(t.text) == "END" {
			// CASE ... END
			depth := 0
			j := end
			for ; j >= 0; j-- {
				u := strings.ToUpper(toks[j].text)
				if toks[j].kind == "ident" && u == "END" {
					depth++
				} else if toks[j].kind == "ident" && u == "CASE" {
					depth--
					if depth == 0 {
						break
					}
				}
			}
			if j >= 0 {
				return j
			}
		}
	}
	// qualified names a.b.c
	for {
		p := prevSig(toks, start)
		if p >= 0 && toks[p].kind == "op" && toks[p].text == "." {
			pp := prevSig(toks, p)
			if pp >= 0 && (toks[pp].kind == "ident" || toks[pp].kind == "qident") {
				start = pp
				continue
			}
		}
		break
	}
	// unary prefix operators
	for {
		p := prevSig(toks, start)
		if p >= 0 && toks[p].kind == "op" && (toks[p].text == "-" || toks[p].text == "+" || toks[p].text == "~") {
			pp := prevSig(toks, p)
			if pp < 0 || toks[pp].kind == "op" || toks[pp].kind == "lparen" || toks[pp].kind == "comma" || (toks[pp].kind == "ident" && sqlKeywordsBeforeOperand[strings.ToUpper(toks[pp].text)]) {
				start = p
				continue
			}
		}
		break
	}
	return start
}

// termEnd finds the end index of the term starting at token index start.
func termEnd(toks []sqlTok, start int) int {
	i := start
	// unary prefixes
	for i < len(toks) && toks[i].kind == "op" && (toks[i].text == "-" || toks[i].text == "+" || toks[i].text == "~") {
		n := nextSig(toks, i)
		if n < 0 {
			return i
		}
		i = n
	}
	t := toks[i]
	end := i
	switch t.kind {
	case "lparen":
		end = matchParen(toks, i)
	case "ident", "qident":
		u := strings.ToUpper(t.text)
		if t.kind == "ident" && u == "CASE" {
			depth := 0
			j := i
			for ; j < len(toks); j++ {
				uu := strings.ToUpper(toks[j].text)
				if toks[j].kind == "ident" && uu == "CASE" {
					depth++
				} else if toks[j].kind == "ident" && uu == "END" {
					depth--
					if depth == 0 {
						break
					}
				}
			}
			if j < len(toks) {
				end = j
			}
			break
		}
		// qualified name
		for {
			n := nextSig(toks, end)
			if n >= 0 && toks[n].kind == "op" && toks[n].text == "." {
				nn := nextSig(toks, n)
				if nn >= 0 && (toks[nn].kind == "ident" || toks[nn].kind == "qident") {
					end = nn
					continue
				}
			}
			break
		}
		if n := nextSig(toks, end); n >= 0 && toks[n].kind == "lparen" {
			end = matchParen(toks, n)
		}
	}
	// COLLATE name
	if n := nextSig(toks, end); n >= 0 && toks[n].kind == "ident" && strings.ToUpper(toks[n].text) == "COLLATE" {
		if nn := nextSig(toks, n); nn >= 0 {
			end = nn
		}
	}
	return end
}

func matchParen(toks []sqlTok, i int) int {
	depth := 0
	for j := i; j < len(toks); j++ {
		if toks[j].kind == "lparen" {
			depth++
		} else if toks[j].kind == "rparen" {
			depth--
			if depth == 0 {
				return j
			}
		}
	}
	return len(toks) - 1
}

func joinToks(toks []sqlTok) string {
	var b strings.Builder
	for _, t := range toks {
		b.WriteString(t.text)
	}
	return b.String()
}

func rewriteJSONArrows(q string) string {
	if !strings.Contains(q, "->") {
		return q
	}
	toks := tokenizeSQL(q)
	for iter := 0; iter < 1000; iter++ {
		idx := -1
		for i, t := range toks {
			if t.kind == "op" && (t.text == "->" || t.text == "->>") {
				idx = i
				break
			}
		}
		if idx < 0 {
			break
		}
		le := prevSig(toks, idx)
		re := nextSig(toks, idx)
		if le < 0 || re < 0 {
			break
		}
		ls := termStart(toks, le)
		for {
			p := prevSig(toks, ls)
			if p >= 0 && toks[p].kind == "op" && toks[p].text == "||" {
				pe := prevSig(toks, p)
				if pe < 0 {
					break
				}
				ls = termStart(toks, pe)
				continue
			}
			break
		}
		rend := termEnd(toks, re)
		fn := "dsq_json_arrow"
		if toks[idx].text == "->>" {
			fn = "dsq_json_arrow2"
		}
		left := joinToks(toks[ls : le+1])
		right := joinToks(toks[re : rend+1])
		repl := fn + "(" + left + ", " + right + ")"
		newToks := append([]sqlTok{}, toks[:ls]...)
		newToks = append(newToks, sqlTok{"ident", repl})
		newToks = append(newToks, toks[rend+1:]...)
		// re-tokenize to allow nested handling
		toks = tokenizeSQL(joinToks(newToks))
	}
	return joinToks(toks)
}

func jsonArrowPath(v sqlValue) string {
	if v.Type() == sqlInteger {
		return "$[" + v.Text() + "]"
	}
	p := v.Text()
	if strings.HasPrefix(p, "$") {
		return p
	}
	if len(p) > 0 && p[0] >= '0' && p[0] <= '9' {
		return "$[" + p + "]"
	}
	if strings.HasPrefix(p, "[") {
		return "$" + p
	}
	return "$." + p
}

func registerJSONArrowFunctions(d *DB) {
	d.CreateFunction("dsq_json_arrow2", 2, true, func(args []sqlValue) (interface{}, error) {
		return d.evalSQL("SELECT json_extract(?, ?)", []interface{}{rawValue(args[0]), jsonArrowPath(args[1])})
	})
	d.CreateFunction("dsq_json_arrow", 2, true, func(args []sqlValue) (interface{}, error) {
		return d.evalSQL(`SELECT CASE json_type(?1, ?2)
			WHEN 'text' THEN json_quote(json_extract(?1, ?2))
			WHEN 'null' THEN 'null'
			WHEN 'true' THEN 'true'
			WHEN 'false' THEN 'false'
			WHEN 'integer' THEN CAST(json_extract(?1, ?2) AS TEXT)
			WHEN 'real' THEN CAST(json_extract(?1, ?2) AS TEXT)
			ELSE json_extract(?1, ?2) END`, []interface{}{rawValue(args[0]), jsonArrowPath(args[1])})
	})
}
