func splitRepeated(n *pqNode, tr [][]pqTriple) [][][]pqTriple {
	var lv []int
	collectLeaves(n, &lv)
	if len(lv) == 0 {
		return nil
	}
	first := tr[lv[0]]
	if len(first) == 0 || first[0].def < n.defLevel {
		return nil
	}
	starts := map[int][]int{}
	for _, l := range lv {
		ts := tr[l]
		var st []int
		for i := range ts {
			if i == 0 || ts[i].rep <= n.repLevel {
				st = append(st, i)
			}
		}
		starts[l] = st
	}
	count := len(starts[lv[0]])
	var out [][][]pqTriple
	for e := 0; e < count; e++ {
		sub := make([][]pqTriple, len(tr))
		for _, l := range lv {
			st := starts[l]
			if e >= len(st) {
				continue
			}
			end := len(tr[l])
			if e+1 < len(st) {
				end = st[e+1]
			}
			sub[l] = tr[l][st[e]:end]
		}
		out = append(out, sub)
	}
	return out
}

// assembleNode builds a value for node n from the triples of one parent instance.
func assembleNode(n *pqNode, tr [][]pqTriple) interface{} {
	if n.repetition == 2 {
		elems := splitRepeated(n, tr)
		if elems == nil {
			return nil
		}
		out := make([]interface{}, 0, len(elems))
		for _, sub := range elems {
			out = append(out, assembleSingle(n, sub))
		}
		return out
	}
	return assembleSingle(n, tr)
}

func nodeDefined(n *pqNode, tr [][]pqTriple) bool {
	var lv []int
	collectLeaves(n, &lv)
	if len(lv) == 0 {
		return false
	}
	ts := tr[lv[0]]
	return len(ts) > 0 && ts[0].def >= n.defLevel
}

func assembleSingle(n *pqNode, tr [][]pqTriple) interface{} {
	if n.leafIdx >= 0 {
		ts := tr[n.leafIdx]
		if len(ts) == 0 {
			return nil
		}
		if ts[0].def < n.maxDef {
			return nil
		}
		return ts[0].val
	}
	if n.repetition == 1 && !nodeDefined(n, tr) {
		return nil
	}
	if (n.convType == 3 || n.convType == 1 || n.convType == 2) && len(n.children) == 1 && n.children[0].repetition == 2 {
		rc := n.children[0]
		elems := splitRepeated(rc, tr)
		if n.convType == 3 {
			out := make([]interface{}, 0, len(elems))
			for _, sub := range elems {
				if rc.leafIdx < 0 && len(rc.children) == 1 {
					out = append(out, assembleNode(rc.children[0], sub))
				} else {
					out = append(out, assembleSingle(rc, sub))
				}
			}
			return out
		}
		m := map[string]interface{}{}
		for _, sub := range elems {
			if rc.leafIdx >= 0 || len(rc.children) < 2 {
				continue
			}
			k := assembleNode(rc.children[0], sub)
			v := assembleNode(rc.children[1], sub)
			m[fmt.Sprintf("%v", k)] = v
		}
		return m
	}
	m := NewOrderedMap()
	for _, c := range n.children {
		m.Set(c.exName, assembleNode(c, tr))
	}
	return m
}

