def zz(n): return (n<<1) ^ (n>>63)
def varint(n):
    n = zz(n) & ((1<<64)-1)
    out=bytearray()
    while True:
        b=n&0x7f; n>>=7
        if n: out.append(b|0x80)
        else: out.append(b); return bytes(out)
def enc_long(n): return varint(n)
def enc_bytes(b): return enc_long(len(b))+b
def enc_str(s): return enc_bytes(s.encode())
def encode(schema, v, named):
    if isinstance(schema, str):
        if schema in named: return encode(named[schema], v, named)
        if schema=='null': return b''
        if schema=='boolean': return b'\x01' if v else b'\x00'
        if schema in ('int','long'): return enc_long(v)
        if schema=='float': return struct.pack('<f',v)
        if schema=='double': return struct.pack('<d',v)
        if schema=='bytes': return enc_bytes(v)
        if schema=='string': return enc_str(v)
    if isinstance(schema, list):
        idx, val = v
        return enc_long(idx)+encode(schema[idx], val, named)
    t=schema['type']
    if t=='record':
        named[schema['name']]=schema
        return b''.join(encode(f['type'], v[f['name']], named) for f in schema['fields'])
    if t=='enum':
        named[schema['name']]=schema
        return enc_long(schema['symbols'].index(v))
    if t=='fixed':
        named[schema['name']]=schema
        return v
    if t=='array':
        if not v: return enc_long(0)
        return enc_long(len(v))+b''.join(encode(schema['items'],x,named) for x in v)+enc_long(0)
    if t=='map':
        if not v: return enc_long(0)
        return enc_long(len(v))+b''.join(enc_str(k)+encode(schema['values'],x,named) for k,x in v.items())+enc_long(0)
    return encode(t, v, named)
def write(path, schema, records, codec='null'):
    sync=os.urandom(16)
    meta={'avro.schema':json.dumps(schema).encode(),'avro.codec':codec.encode()}
    out=bytearray(b'Obj\x01')
    out+=enc_long(len(meta))
