cd /workspace && cat >> sqlrewrite.go <<'EOF'

func upperIdent(t sqlTok) string {
	if t.kind == "ident" {
		return strings.ToUpper(t.text)
	}
	return ""
}

// sigIndexes returns indexes of significant tokens.
func sigIndexes(toks []sqlTok) []int {
	var out []int
	for i, t := range toks {
		if isSignificant(t) {
			out = append(out, i)
		}
	}
	return out
}

func rewriteDistinctFrom(toks []sqlTok) []sqlTok {
	sig := sigIndexes(toks)
	for k := 0; k+2 < len(sig); k++ {
		if upperIdent(toks[sig[k]]) != "IS" {
			continue
		}
		j := k + 1
		not := false
		if upperIdent(toks[sig[j]]) == "NOT" {
			not = true
			j++
		}
		if j+1 < len(sig) && upperIdent(toks[sig[j]]) == "DISTINCT" && upperIdent(toks[sig[j+1]]) == "FROM" {
			// replace tokens from sig[k] to sig[j+1]
			repl := "IS NOT"
			if not {
				repl = "IS"
			}
			newToks := append([]sqlTok{}, toks[:sig[k]]...)
			newToks = append(newToks, sqlTok{"ident", repl})
			newToks = append(newToks, toks[sig[j+1]+1:]...)
			return rewriteDistinctFrom(newToks)
		}
	}
	return toks
}

func tokDepths(toks []sqlTok) []int {
	d := make([]int, len(toks))
	depth := 0
	for i, t := range toks {
		if t.kind == "rparen" {
			depth--
		}
		d[i] = depth
		if t.kind == "lparen" {
			depth++
		}
	}
	return d
}

func rewriteHavingWithoutGroup(toks []sqlTok) []sqlTok {
	depth := tokDepths(toks)
	for i, t := range toks {
		if upperIdent(t) != "HAVING" {
			continue
		}
		hasGroup := false
		for j := i - 1; j >= 0; j-- {
			if depth[j] < depth[i] {
				break
			}
			if depth[j] != depth[i] {
				continue
			}
			u := upperIdent(toks[j])
			if u == "GROUP" {
				hasGroup = true
				break
			}
			if u == "SELECT" {
				break
			}
		}
		if !hasGroup {
			newToks := append([]sqlTok{}, toks[:i]...)
			newToks = append(newToks, sqlTok{"ident", "GROUP"}, sqlTok{"ws", " "}, sqlTok{"ident", "BY"}, sqlTok{"ws", " "}, sqlTok{"ident", "NULL"}, sqlTok{"ws", " "})
			newToks = append(newToks, toks[i:]...)
			return rewriteHavingWithoutGroup(newToks)
		}
	}
	return toks
}

var clauseEnd = map[string]bool{"WHERE": true, "GROUP": true, "ORDER": true, "LIMIT": true, "HAVING": true, "WINDOW": true, "UNION": true, "EXCEPT": true, "INTERSECT": true}

// rewriteRightJoin turns "FROM a RIGHT [OUTER] JOIN b ON c" into "FROM b LEFT JOIN a ON c".
func rewriteRightJoin(toks []sqlTok) []sqlTok {
	depth := tokDepths(toks)
	sig := sigIndexes(toks)
	for k, ti := range sig {
		if upperIdent(toks[ti]) != "RIGHT" {
			continue
		}
		d := depth[ti]
		// find FROM before at same depth
		fromK := -1
		for j := k - 1; j >= 0; j-- {
			if depth[sig[j]] < d {
				break
			}
			if depth[sig[j]] == d && upperIdent(toks[sig[j]]) == "FROM" {
				fromK = j
				break
			}
		}
		if fromK < 0 {
			continue
		}
		left := sig[fromK+1 : k]
		// table term: name [AS] [alias]
		parseTerm := func(ids []int) (name string, ref string, ok bool) {
			if len(ids) == 0 || len(ids) > 3 {
				return "", "", false
			}
			for _, x := range ids {
				if toks[x].kind != "ident" && toks[x].kind != "qident" {
					return "", "", false
				}
			}
			name = toks[ids[0]].text
			ref = name
			if len(ids) == 2 {
				ref = toks[ids[1]].text
			} else if len(ids) == 3 {
				if upperIdent(toks[ids[1]]) != "AS" {
					return "", "", false
				}
				ref = toks[ids[2]].text
			}
			return name, ref, true
		}
		_, lref, ok := parseTerm(left)
		if !ok {
			continue
		}
		j := k + 1
		if j < len(sig) && upperIdent(toks[sig[j]]) == "OUTER" {
			j++
		}
		if j >= len(sig) || upperIdent(toks[sig[j]]) != "JOIN" {
			continue
		}
		j++
		start2 := j
		for j < len(sig) && upperIdent(toks[sig[j]]) != "ON" && depth[sig[j]] == d {
			j++
		}
		if j >= len(sig) {
			continue
		}
		_, rref, ok := parseTerm(sig[start2:j])
		if !ok {
			continue
		}
		onK := j
		// end of ON condition
		e := onK + 1
		for e < len(sig) {
			x := sig[e]
			if depth[x] < d || (depth[x] == d && (clauseEnd[upperIdent(toks[x])] || toks[x].kind == "rparen" || toks[x].text == ";" || upperIdent(toks[x]) == "JOIN" || upperIdent(toks[x]) == "LEFT" || upperIdent(toks[x]) == "INNER" || upperIdent(toks[x]) == "CROSS" || upperIdent(toks[x]) == "RIGHT" || upperIdent(toks[x]) == "FULL" || toks[x].kind == "comma")) {
				break
			}
			e++
		}
		if e < len(sig) {
			u := upperIdent(toks[sig[e]])
			if u == "JOIN" || u == "LEFT" || u == "INNER" || u == "CROSS" || u == "RIGHT" || u == "FULL" || toks[sig[e]].kind == "comma" {
				continue
			}
		}
		leftText := joinToks(toks[left[0] : left[len(left)-1]+1])
		rightText := joinToks(toks[sig[start2] : sig[onK-1]+1])
		var newToks []sqlTok
		newToks = append(newToks, toks[:left[0]]...)
		newToks = append(newToks, sqlTok{"ident", rightText + " LEFT JOIN " + leftText + " "})
		newToks = append(newToks, toks[sig[onK]:]...)
		// expand bare * in select list
		out := tokenizeSQL(joinToks(newToks))
		odepth := tokDepths(out)
		osig := sigIndexes(out)
		// locate the FROM again: find the SELECT at depth d before position
		for q := 0; q < len(osig); q++ {
			x := osig[q]
			if odepth[x] == d && upperIdent(out[x]) == "SELECT" {
				// check the select list is exactly "*" (optionally DISTINCT/ALL)
				r := q + 1
				if r < len(osig) && (upperIdent(out[osig[r]]) == "DISTINCT" || upperIdent(out[osig[r]]) == "ALL") {
					r++
				}
				if r+1 < len(osig) && out[osig[r]].text == "*" && upperIdent(out[osig[r+1]]) == "FROM" {
					star := osig[r]
					var nt []sqlTok
					nt = append(nt, out[:star]...)
					nt = append(nt, sqlTok{"ident", lref + ".*, " + rref + ".*"})
					nt = append(nt, out[star+1:]...)
					out = tokenizeSQL(joinToks(nt))
				}
				break
			}
		}
		return rewriteRightJoin(out)
	}
	return toks
}

func rewriteCompat(q string) string {
	u := strings.ToUpper(q)
	if !strings.Contains(u, "DISTINCT") && !strings.Contains(u, "HAVING") && !strings.Contains(u, "RIGHT") {
		return q
	}
	toks := tokenizeSQL(q)
	toks = rewriteDistinctFrom(toks)
	toks = rewriteHavingWithoutGroup(toks)
	toks = rewriteRightJoin(toks)
	return joinToks(toks)
}
